insert into exam_sections(paper_id,type,item_count,position,status) select id,'cloze',1,1,'published' from exam_papers where year=2010 on conflict(paper_id,type) do update set item_count=1,status='published';
insert into cloze_tasks(section_id,content,status) select s.id,'{"year":2010,"directions":"Read the following text. Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET. (10 points)","paragraphs":["The outbreak of swine flu that was first detected in Mexico was declared a global epidemic on June 11, 2009. It is the first worldwide epidemic {{1}} by the World Health Organization in 41 years.","The heightened alert {{2}} an emergency meeting with flu experts in Geneva that assembled after a sharp rise in cases in Australia, and rising {{3}} in Britain, Japan, Chile and elsewhere.","But the epidemic is “ {{4}} ” in severity, according to Margaret Chan, the organization’s director general, {{5}} the overwhelming majority of patients experiencing only mild symptoms and a full recovery, often in the {{6}} of any medical treatment.","The outbreak came to global {{7}} in late April 2009, when Mexican authorities noted an unusually large number of hospitalizations and deaths {{8}} healthy adults. As much of Mexico City shut down at the height of a panic, cases began to {{9}} in New York City, the southwestern United States and around the world.","In the United States, new cases seemed to fade {{10}} warmer weather arrived. But in late September 2009, officials reported there was {{11}} flu activity in almost every state and that virtually all the {{12}} tested are the new swine flu, also known as (A) H1N1, not seasonal flu. In the U.S., it has {{13}} more than one million people, and caused more than 600 deaths and more than 6,000 hospitalizations.","Federal health officials {{14}} Tamiflu for children from the national stockpile and began {{15}} orders from the states for the new swine flu vaccine. The new vaccine, which is different from the annual flu vaccine, is {{16}} ahead of expectations. More than three million doses were to be made available in early October 2009, though most of those {{17}} doses were of the FluMist nasal spray type, which is not {{18}} for pregnant women, people over 50 or those with breathing difficulties, heart disease or several other {{19}} . But it was still possible to vaccinate people in other high-risk groups: health care workers, people {{20}} infants and healthy young people."],"questions":[{"number":1,"options":["criticized","appointed","commented","designated"]},{"number":2,"options":["proceeded","activated","followed","prompted"]},{"number":3,"options":["digits","numbers","amounts","sums"]},{"number":4,"options":["moderate","normal","unusual","extreme"]},{"number":5,"options":["with","in","from","by"]},{"number":6,"options":["progress","absence","presence","favor"]},{"number":7,"options":["reality","phenomenon","concept","notice"]},{"number":8,"options":["over","for","among","to"]},{"number":9,"options":["stay up","crop up","fill up","cover up"]},{"number":10,"options":["as","if","unless","until"]},{"number":11,"options":["excessive","enormous","significant","magnificent"]},{"number":12,"options":["categories","examples","patterns","samples"]},{"number":13,"options":["imparted","immersed","injected","infected"]},{"number":14,"options":["released","relayed","relieved","remained"]},{"number":15,"options":["placing","delivering","taking","giving"]},{"number":16,"options":["feasible","available","reliable","applicable"]},{"number":17,"options":["prevalent","principal","innovative","initial"]},{"number":18,"options":["presented","restricted","recommended","introduced"]},{"number":19,"options":["problems","issues","agonies","sufferings"]},{"number":20,"options":["involved in","caring for","concerned with","warding off"]}],"sourcePages":[1,2]}'::jsonb,'published' from exam_sections s join exam_papers p on p.id=s.paper_id where p.year=2010 and s.type='cloze' on conflict(section_id) do update set content=excluded.content,status='published';
insert into private.cloze_keys(task_id,keys) select t.id,'[{"number":1,"answer":"D","explanation":"此处指世界卫生组织“指定”的全球流行病，designated 意为“指定，认定”，符合语境。criticized（批评）与“宣布流行病”矛盾；appointed（任命）用于人；commented（评论）不搭配“epidemic”。"},{"number":2,"answer":"C","explanation":"“提高的警报”之后“紧接着”是紧急会议，followed 表示“紧随其后”，符合时间顺序。proceeded 需接 to/with；activated（激活）不搭配“alert”；prompted（促使）逻辑反了，应是会议被警报促使。"},{"number":3,"answer":"B","explanation":"此处指英国等地“上升的病例数字”，numbers 与 rising 搭配表示数量增加。digits 指具体数字位；amounts 用于不可数；sums 指金额或总数，均不用于病例数。"},{"number":4,"answer":"A","explanation":"后文说绝大多数患者症状轻微并康复，说明严重程度“温和”，moderate 意为“中等的，温和的”。normal（正常）不强调程度轻；unusual（不寻常）与后文矛盾；extreme（极端）相反。"},{"number":5,"answer":"A","explanation":"此处是 with 复合结构“with + 宾语 + 现在分词”，表示伴随情况：绝大多数患者经历轻微症状。in、from、by 均不能构成这种独立主格结构。"},{"number":6,"answer":"B","explanation":"in the absence of 是固定搭配，意为“在没有……的情况下”，此处指往往没有任何医疗处理就康复了。progress（进展）、presence（存在）、favor（赞同）均不构成此义。"},{"number":7,"answer":"D","explanation":"come to global notice 意为“引起全球关注”，notice 指注意。reality（现实）搭配 come to reality 不自然；phenomenon（现象）和 concept（概念）与 come to 搭配不当。"},{"number":8,"answer":"C","explanation":"among 表示“在……之中”，此处指在健康成年人中住院和死亡人数异常多。over（超过）不接 healthy adults 表示范围；for 和 to 也不表示“在群体中”。"},{"number":9,"answer":"B","explanation":"crop up 意为“突然出现”，指病例在纽约等地开始冒出来。stay up（熬夜）、fill up（填满）、cover up（掩盖）均不符合“病例出现”的语境。"},{"number":10,"answer":"A","explanation":"as 引导时间状语从句，意为“随着天气变暖”，新病例似乎减少了。if（如果）、unless（除非）、until（直到）均不能表示“随着”的同步变化。"},{"number":11,"answer":"C","explanation":"此处描述2009年9月下旬官员报告几乎每个州都有流感活动，强调其重要性或可观程度。significant意为“显著的，重要的”，符合语境。excessive“过度的”含贬义，enormous“巨大的”多指体积或数量，magnificent“壮丽的”不搭配。"},{"number":12,"answer":"D","explanation":"此处指 virtually all the samples tested，即“几乎所有检测的样本”都是新猪流感。samples意为“样本”，符合医学检测语境。categories“类别”、examples“例子”、patterns“模式”均不切合检测对象。"},{"number":13,"answer":"D","explanation":"句子表示猪流感在美国感染了超过一百万人。infected意为“感染”，与疾病传播语境吻合。imparted“传授”、immersed“沉浸”、injected“注射”均不能表示疾病传染。"},{"number":14,"answer":"A","explanation":"联邦卫生官员从国家储备中释放Tamiflu给儿童。released意为“释放，发放”，符合调配药品的语境。relayed“转播”、relieved“缓解”、remained“保持”均不搭配。"},{"number":15,"answer":"C","explanation":"官员开始接受各州对新猪流感疫苗的订单。taking orders是固定搭配，意为“接受订单”。placing“放置”、delivering“递送”、giving“给予”均不能与orders构成“接受订单”之意。"},{"number":16,"answer":"B","explanation":"新疫苗比预期更早可用。available意为“可获得的”，与ahead of expectations搭配，表示提前面世。feasible“可行的”、reliable“可靠的”、applicable“适用的”均不强调时间上的提前。"},{"number":17,"answer":"D","explanation":"此处指最初生产的那批疫苗，即“那些初始剂量”。initial意为“最初的”，与后文“2009年10月初”的时间点呼应。prevalent“流行的”、principal“主要的”、innovative“创新的”均不切合批次含义。"},{"number":18,"answer":"C","explanation":"鼻喷型流感疫苗不推荐用于孕妇、50岁以上或有呼吸疾病等人群。recommended意为“推荐”，符合医学建议语境。presented“呈现”、restricted“限制”、introduced“介绍”均不如recommended准确。"},{"number":19,"answer":"A","explanation":"此处列举呼吸系统疾病、心脏病或其他几个问题。problems意为“问题”，与diseases并列，指健康问题。issues多指争议话题，agonies“极度痛苦”、sufferings“苦难”语义过重且不搭配。"},{"number":20,"answer":"B","explanation":"此处列举其他高风险人群：医护人员、照顾婴儿的人和健康年轻人。caring for意为“照顾”，符合婴儿需要照护的语境。involved in“参与”、concerned with“涉及”、warding off“避开”均不能准确表达照护关系。"}]'::jsonb from cloze_tasks t join exam_sections s on s.id=t.section_id join exam_papers p on p.id=s.paper_id where p.year=2010 on conflict(task_id) do update set keys=excluded.keys;
insert into exam_sections(paper_id,type,item_count,position,status) select id,'cloze',1,1,'published' from exam_papers where year=2011 on conflict(paper_id,type) do update set item_count=1,status='published';
insert into cloze_tasks(section_id,content,status) select s.id,'{"year":2011,"directions":"Read the following text. Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET. (10 points)","paragraphs":["The Internet affords anonymity to its users, a blessing to privacy and freedom of speech. But that very anonymity is also behind the explosion of cyber-crime that has {{1}} across the Web.","Can privacy be preserved {{2}} bringing safety and security to a world that seems increasingly {{3}} ?","Last month, Howard Schmidt, the nation’s cyber-czar, offered the federal government a {{4}} to make the Web a safer place — a “voluntary trusted identity” system that would be the high-tech {{5}} of a physical key, a fingerprint and a photo ID card, all rolled {{6}} one. The system might use a smart identity card, or a digital credential {{7}} to a specific computer, and would authenticate users at a range of online services.","The idea is to {{8}} a federation of private online identity systems. Users could {{9}} which system to join, and only registered users whose identities have been authenticated could navigate those systems. The approach contrasts with one that would require an Internet driver’s license {{10}} by the government.","Google and Microsoft are among companies that already have these “single sign-on” systems that make it possible for users to {{11}} just once but use many different services.","{{12}} , the approach would create a “walled garden” in cyberspace, with safe “neighborhoods” and bright “streetlights” to establish a sense of a {{13}} community.","Mr. Schmidt described it as a “voluntary ecosystem” in which “individuals and organizations can complete online transactions with {{14}} , trusting the identities of each other and the identities of the infrastructure {{15}} which the transaction runs.”","Still, the administration’s plan has {{16}} privacy rights activists. Some applaud the approach; others are concerned. It seems clear that such a scheme is an initiative push toward what would {{17}} be a compulsory Internet “driver’s license” mentality.","The plan has also been greeted with {{18}} by some computer security experts, who worry that the “voluntary ecosystem” envisioned by Mr. Schmidt would still leave much of the Internet {{19}} . They argue that all Internet users should be {{20}} to register and identify themselves, in the same way that drivers must be licensed to drive on public roads."],"questions":[{"number":1,"options":["swept","skipped","walked","ridden"]},{"number":2,"options":["for","within","while","though"]},{"number":3,"options":["careless","lawless","pointless","helpless"]},{"number":4,"options":["reason","reminder","compromise","proposal"]},{"number":5,"options":["information","interference","entertainment","equivalent"]},{"number":6,"options":["by","into","from","over"]},{"number":7,"options":["linked","directed","chained","compared"]},{"number":8,"options":["dismiss","discover","create","improve"]},{"number":9,"options":["recall","suggest","select","realize"]},{"number":10,"options":["released","issued","distributed","delivered"]},{"number":11,"options":["carry on","linger on","set in","log in"]},{"number":12,"options":["In vain","In effect","In return","In contrast"]},{"number":13,"options":["trusted","modernized","thriving","competing"]},{"number":14,"options":["caution","delight","confidence","patience"]},{"number":15,"options":["on","after","beyond","across"]},{"number":16,"options":["divided","disappointed","protected","united"]},{"number":17,"options":["frequently","incidentally","occasionally","eventually"]},{"number":18,"options":["skepticism","tolerance","indifference","enthusiasm"]},{"number":19,"options":["manageable","defendable","vulnerable","invisible"]},{"number":20,"options":["invited","appointed","allowed","forced"]}],"sourcePages":[1,2,3]}'::jsonb,'published' from exam_sections s join exam_papers p on p.id=s.paper_id where p.year=2011 and s.type='cloze' on conflict(section_id) do update set content=excluded.content,status='published';
insert into private.cloze_keys(task_id,keys) select t.id,'[{"number":1,"answer":"A","explanation":"swept across意为“席卷”，与explosion of cyber-crime搭配，表示网络犯罪在网络上迅速蔓延。skipped“跳过”、walked“走过”、ridden“骑过”均不能与across搭配表达蔓延之意，且与犯罪搭配不当。"},{"number":2,"answer":"C","explanation":"while引导让步状语，意为“在……的同时”，句意：在给日益无法无天的世界带来安全的同时，隐私能否得到保护？for、within、though均不能在此构成“在……的同时”的让步逻辑，though虽表让步但需接从句，此处不搭配。"},{"number":3,"answer":"B","explanation":"lawless“无法无天的”与上文cyber-crime及下文bring safety and security形成呼应，说明网络世界缺乏法律约束。careless“粗心的”、pointless“无意义的”、helpless“无助的”均不能准确描述网络犯罪泛滥所体现的失序状态。"},{"number":4,"answer":"D","explanation":"proposal“提议”与offered the federal government搭配，指Schmidt提出一项方案，下文a “voluntary trusted identity” system正是该提议内容。reason“理由”、reminder“提醒”、compromise“妥协”均不符合“提出方案”的语义。"},{"number":5,"answer":"D","explanation":"equivalent“等同物”与of a physical key, a fingerprint and a photo ID card搭配，说明高科技系统相当于实体钥匙、指纹和照片身份证的结合。information“信息”、interference“干扰”、entertainment“娱乐”均不能表达“等同物”之意。"},{"number":6,"answer":"B","explanation":"rolled into one是固定搭配，意为“合为一体”，指钥匙、指纹和身份证三者合而为一。by、from、over均不能与rolled和one构成该固定短语，语义不通。"},{"number":7,"answer":"A","explanation":"linked to意为“连接到”，指数字凭证与特定计算机相连。directed“指向”、chained“拴住”、compared“比较”均不能准确表达凭证与计算机之间的关联关系，且搭配不当。"},{"number":8,"answer":"C","explanation":"create“创建”与a federation of private online identity systems搭配，指建立私人在线身份系统的联盟。dismiss“解散”、discover“发现”、improve“改进”均不符合从无到有建立联盟的语境。"},{"number":9,"answer":"C","explanation":"select“选择”与which system to join搭配，指用户可以选择加入哪个系统。recall“回忆”、suggest“建议”、realize“意识到”均不能与which system to join构成合理搭配，无法表达自主选择之意。"},{"number":10,"answer":"B","explanation":"issued“颁发”与driver’s license搭配，指由政府颁发的互联网“驾照”。released“发布”、distributed“分发”、delivered“递送”均不能准确表达政府颁发许可证的语义，搭配不当。"},{"number":11,"answer":"D","explanation":"此处描述“单点登录”系统让用户只需一次{{11}}就能使用多种服务。log in意为“登录”，与“single sign-on”及后文“use many different services”呼应。carry on（继续）、linger on（逗留）、set in（开始）均不表示登录，无法与“once”搭配表达一次认证。"},{"number":12,"answer":"B","explanation":"前文说用户可自选系统，本句说该方式会创建“walled garden”，形成安全社区，这是该方式实际产生的效果。In effect意为“实际上，事实上”，符合逻辑。In vain（徒劳）、In return（作为回报）、In contrast（相反）均与上下文不符。"},{"number":13,"answer":"A","explanation":"本句描述“walled garden”内有安全“街区”和明亮“路灯”，目的是建立一种社区感。结合后文“trusting the identities”，这种社区应是“可信的”。trusted意为“受信任的”，符合语境。modernized（现代化的）、thriving（繁荣的）、competing（竞争的）均未体现安全信任的核心。"},{"number":14,"answer":"C","explanation":"Schmidt描述“自愿生态系统”中个人和组织能完成在线交易，且互相信任身份。with confidence意为“有信心地”，与“trusting”呼应。caution（谨慎）、delight（高兴）、patience（耐心）均不能体现因信任而安心交易的含义。"},{"number":15,"answer":"A","explanation":"此处指交易运行所依赖的基础设施，the infrastructure {{15}} which the transaction runs是“介词+which”引导的定语从句。run on意为“依靠……运行”，on which即“在……上运行”。after、beyond、across均不能与run搭配表示“依赖”。"},{"number":16,"answer":"A","explanation":"后文说“Some applaud the approach; others are concerned”，表明隐私权利活动人士意见分歧。has divided意为“使……产生分歧”，符合语境。disappointed（使失望）、protected（保护）、united（团结）均与“有人赞扬有人担忧”矛盾。"},{"number":17,"answer":"D","explanation":"本句说该方案是朝着某种强制性的互联网“驾照”心态迈进的举措。eventually意为“最终”，表示这种心态可能最终形成，符合“initiative push toward”的渐进含义。frequently（频繁地）、incidentally（偶然地）、occasionally（偶尔地）均不能表达最终结果。"},{"number":18,"answer":"A","explanation":"后文说计算机安全专家担心“自愿生态系统”仍会让互联网大部分{{19}}，他们主张所有用户应被强制注册。这说明专家持怀疑态度。skepticism意为“怀疑”，符合语境。tolerance（容忍）、indifference（漠不关心）、enthusiasm（热情）均与“worry”矛盾。"},{"number":19,"answer":"C","explanation":"专家担心“自愿生态系统”仍会让互联网大部分处于不安全状态。vulnerable意为“易受攻击的，脆弱的”，与“worry”及后文要求强制注册的论点一致。manageable（可管理的）、defendable（可防御的）、invisible（看不见的）均不能表达安全担忧。"},{"number":20,"answer":"D","explanation":"专家主张所有互联网用户都应被{{20}}注册并表明身份，就像司机必须持证上路一样。forced意为“被迫”，与“must be licensed”的强制含义一致。invited（邀请）、appointed（任命）、allowed（允许）均不能体现“必须”的强制性。"}]'::jsonb from cloze_tasks t join exam_sections s on s.id=t.section_id join exam_papers p on p.id=s.paper_id where p.year=2011 on conflict(task_id) do update set keys=excluded.keys;
insert into exam_sections(paper_id,type,item_count,position,status) select id,'cloze',1,1,'published' from exam_papers where year=2012 on conflict(paper_id,type) do update set item_count=1,status='published';
insert into cloze_tasks(section_id,content,status) select s.id,'{"year":2012,"directions":"Read the following text. Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET. (10 points)","paragraphs":["Millions of Americans and foreigners see G.I. Joe as a mindless war toy, the symbol of American military adventurism, but that’s not how it used to be. To the men and women who {{1}} in World War Ⅱ and the people they liberated, the G.I. was the {{2}} man grown into hero, the poor farm kid torn away from his home, the guy who {{3}} all the burdens of battle, who slept in cold foxholes, who went without the {{4}} of food and shelter, who stuck it out and drove back the Nazi reign of murder. This was not a volunteer soldier, not someone well paid, {{5}} an average guy, up {{6}} the best trained, best equipped, fiercest, most brutal enemies seen in centuries.","His name isn’t much. G.I. is just a military abbreviation {{7}} Government Issue, and it was on all of the articles {{8}} to soldiers. And Joe? A common name for a guy who never {{9}} it to the top. Joe Blow, Joe Palooka, Joe Magrac… a working class name. The United States has {{10}} had a president or vice-president or secretary of state Joe.","G.I. Joe had a {{11}} career fighting German, Japanese, and Korean troops. He appears as a character, or a {{12}} of American personalities, in the 1945 movie The Story of G.I. Joe , based on the last days of war correspondent Ernie Pyle. Some of the soldiers Pyle {{13}} portrayed themselves in the film. Pyle was famous for covering the {{14}} side of the war, writing about the dirt-snow-and-mud soldiers, not how many miles were {{15}} or what towns were captured or liberated. His reports {{16}} the “Willie” cartoons of famed Stars and Stripes artist Bill Maulden. Both men {{17}} the dirt and exhaustion of war, the {{18}} of civilization that the soldiers shared with each other and the civilians: coffee, tobacco, whiskey, shelter, sleep. {{19}} Egypt, France, and a dozen more countries, G.I. Joe was any American soldier, {{20}} the most important person in their lives."],"questions":[{"number":1,"options":["served","performed","rebelled","betrayed"]},{"number":2,"options":["actual","common","special","normal"]},{"number":3,"options":["loaded","eased","removed","bore"]},{"number":4,"options":["necessities","facilities","commodities","properties"]},{"number":5,"options":["and","nor","but","hence"]},{"number":6,"options":["for","into","from","against"]},{"number":7,"options":["implying","meaning","symbolizing","claiming"]},{"number":8,"options":["handed out","turned over","brought back","passed down"]},{"number":9,"options":["pushed","got","made","managed"]},{"number":10,"options":["ever","never","either","neither"]},{"number":11,"options":["disguised","disturbed","disputed","distinguished"]},{"number":12,"options":["company","community","collection","colony"]},{"number":13,"options":["employed","appointed","interviewed","questioned"]},{"number":14,"options":["human","military","political","ethical"]},{"number":15,"options":["ruined","commuted","patrolled","gained"]},{"number":16,"options":["paralleled","counteracted","duplicated","contradicted"]},{"number":17,"options":["neglected","emphasized","avoided","admired"]},{"number":18,"options":["stages","illusions","fragments","advances"]},{"number":19,"options":["With","To","Among","Beyond"]},{"number":20,"options":["on the contrary","by this means","from the outset","at that point"]}],"sourcePages":[1,2]}'::jsonb,'published' from exam_sections s join exam_papers p on p.id=s.paper_id where p.year=2012 and s.type='cloze' on conflict(section_id) do update set content=excluded.content,status='published';
insert into private.cloze_keys(task_id,keys) select t.id,'[{"number":1,"answer":"A","explanation":"此处描述在二战中服役的男女，serve in World War II 是固定搭配，表示“在二战中服役”。perform 通常不与 in 搭配表示服役；rebel 意为“反叛”，betray 意为“背叛”，均与上下文赞扬士兵的语境不符。"},{"number":2,"answer":"B","explanation":"the common man 是固定表达，意为“普通人”，与后文“grown into hero”形成对比，强调普通人成为英雄。actual 意为“实际的”，special 意为“特殊的”，normal 虽可表示“正常的”，但 common man 更符合英语惯用搭配。"},{"number":3,"answer":"D","explanation":"bear burdens 是固定搭配，意为“承担负担”，此处指士兵承担战争的重负。load 意为“装载”，ease 意为“减轻”，remove 意为“移除”，均不能与 burdens 搭配表达“承担”之意。"},{"number":4,"answer":"A","explanation":"the necessities of food and shelter 指食物和住所等生活必需品，necessities 意为“必需品”。facilities 意为“设施”，commodities 意为“商品”，properties 意为“财产”，均不符合此处“缺乏食物和住所等基本需求”的语境。"},{"number":5,"answer":"C","explanation":"此处与前文“not a volunteer soldier, not someone well paid”构成“not...but...”结构，表示“不是……而是……”，强调士兵是普通人。and 表并列，nor 表否定，hence 表因果，均不符合逻辑关系。"},{"number":6,"answer":"D","explanation":"up against 是固定短语，意为“面对，对抗”，此处指普通士兵面对训练有素、装备精良的敌人。up for 意为“准备好”，up into 和 up from 均不是固定搭配，且不符合语境。"},{"number":7,"answer":"B","explanation":"meaning 意为“意思是”，此处解释 G.I. 是 Government Issue 的缩写，表示其含义。implying 意为“暗示”，symbolizing 意为“象征”，claiming 意为“声称”，均不能准确表达缩写与全称之间的释义关系。"},{"number":8,"answer":"A","explanation":"handed out to soldiers 意为“分发给士兵”，指印有 G.I. 字样的物品被发放给士兵。turned over 意为“移交”，brought back 意为“带回”，passed down 意为“传下”，均不符合“分发物品”的语境。"},{"number":9,"answer":"C","explanation":"make it to the top 是固定表达，意为“成功到达顶峰”，此处指从未跻身高层的普通人。push 意为“推动”，get 需搭配 to 但不如 make it 地道，manage 意为“设法完成”，均不如 make it 符合“成功”的惯用表达。"},{"number":10,"answer":"B","explanation":"never 表示“从未”，此处强调美国从未有过名叫 Joe 的总统、副总统或国务卿，突出 Joe 是普通人的名字。ever 意为“曾经”，either 和 neither 用于两者，均不符合“从未有过”的否定强调。"},{"number":11,"answer":"D","explanation":"此处修饰G.I. Joe的军旅生涯，指其“杰出的、卓越的”经历，distinguished career为固定搭配。disguised“伪装的”、disturbed“受扰的”、disputed“有争议的”均不能与career搭配表达“辉煌经历”之意，且与后文转战多国敌人的语境不符。"},{"number":12,"answer":"C","explanation":"此处指他作为“美国众多个性的集合体”出现，collection意为“集合、汇集”，与of American personalities搭配。company“公司/陪伴”、community“社区”、colony“殖民地”均不能表达“人物特征的汇集”这一含义。"},{"number":13,"answer":"C","explanation":"Pyle是战地记者，此处指他“采访”过的士兵，interviewed符合记者身份。employed“雇用”、appointed“任命”、questioned“盘问”均与记者采访报道的语境不符。"},{"number":14,"answer":"A","explanation":"后文写他报道泥雪中的士兵、不写攻占多少城镇，说明他关注战争的“人性”一面，human side符合。military“军事的”与后文“不写军事进展”矛盾，political“政治的”、ethical“伦理的”均无对应信息。"},{"number":15,"answer":"D","explanation":"此处与captured、liberated并列，指“推进了多少英里”，gained miles表示取得/推进里程。ruined“毁坏”、commuted“通勤”、patrolled“巡逻”均不能与how many miles搭配表达战线推进之意。"},{"number":16,"answer":"A","explanation":"Pyle的报道与Bill Maulden的“Willie”漫画“相似、平行”，paralleled意为“与……相似/并行”。counteracted“抵消”、duplicated“复制”、contradicted“反驳”均不符合两者风格相近的语境。"},{"number":17,"answer":"B","explanation":"两人都“强调”战争的肮脏与疲惫，emphasized符合。neglected“忽视”、avoided“回避”与后文列举他们共同关注的事物矛盾，admired“钦佩”不能直接接the dirt and exhaustion作宾语表达此意。"},{"number":18,"answer":"C","explanation":"此处指文明在战火中残存的“碎片”，fragments of civilization意为文明的碎片，与咖啡、烟草等具体事物对应。stages“阶段”、illusions“幻觉”、advances“进步”均不能准确表达战地生活中文明点滴残存的含义。"},{"number":19,"answer":"B","explanation":"此处表示“在埃及、法国等许多国家中”，Among意为“在……之中”，符合G.I. Joe在这些国家被视为任何美国士兵的语境。With“和”、To“对”、Beyond“超出”均不能表达范围之内的含义。"},{"number":20,"answer":"D","explanation":"此处指对 civilians 而言，G.I. Joe 在“那时那地”是他们生命中最重要的人，at that point意为“在那时/那一点上”。on the contrary“相反”、by this means“用这种方式”、from the outset“从一开始”均不符合此处强调特定情境下意义的逻辑。"}]'::jsonb from cloze_tasks t join exam_sections s on s.id=t.section_id join exam_papers p on p.id=s.paper_id where p.year=2012 on conflict(task_id) do update set keys=excluded.keys;
insert into exam_sections(paper_id,type,item_count,position,status) select id,'cloze',1,1,'published' from exam_papers where year=2013 on conflict(paper_id,type) do update set item_count=1,status='published';
insert into cloze_tasks(section_id,content,status) select s.id,'{"year":2013,"directions":"Read the following text. Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET. (10 points)","paragraphs":["Given the advantages of electronic money, you might think that we would move quickly to the cashless society in which all payments are made electronically. {{1}} , a true cashless society is probably not around the corner. Indeed, predictions have been {{2}} for two decades but have not yet come to fruition. For example, Business Week predicted in 1975 that electronic means of payment would soon “revolutionize the very {{3}} of money itself,” only to {{4}} itself several years later. Why has the movement to a cashless society been so {{5}} in coming?","Although electronic means of payment may be more efficient than a payments system based on paper, several factors work {{6}} the disappearance of the paper system. First, it is very {{7}} to set up the computer, card reader, and telecommunications networks necessary to make electronic money the {{8}} form of payment. Second, paper checks have the advantage that they {{9}} receipts, something that many consumers are unwilling to {{10}} . Third, the use of paper checks gives consumers several days of “float” — it takes several days {{11}} a check is cashed and funds are {{12}} from the issuer’s account, which means that the writer of the check can earn interest on the funds in the meantime. {{13}} electronic payments are immediate, they eliminate the float for the consumer.","Fourth, electronic means of payment may {{14}} security and privacy concerns. We often hear media reports that an unauthorized hacker has been able to access a computer database and to alter information {{15}} there. The fact that this is not an {{16}} occurrence means that dishonest persons might be able to access bank accounts in electronic payments systems and {{17}} from someone else’s accounts. The {{18}} of this type of fraud is no easy task, and a new field of computer science is developing to {{19}} security issues. A further concern is that the use of electronic means of payment leaves an electronic {{20}} that contains a large amount of personal data. There are concerns that government, employers, and marketers might be able to access these data, thereby violating our privacy."],"questions":[{"number":1,"options":["However","Moreover","Therefore","Otherwise"]},{"number":2,"options":["around","back","over","off"]},{"number":3,"options":["power","concept","history","role"]},{"number":4,"options":["reward","resist","resume","reverse"]},{"number":5,"options":["silent","sudden","slow","steady"]},{"number":6,"options":["for","against","with","on"]},{"number":7,"options":["expensive","imaginative","sensitive","productive"]},{"number":8,"options":["dominant","original","temporary","similar"]},{"number":9,"options":["collect","provide","copy","print"]},{"number":10,"options":["give up","take over","bring back","pass down"]},{"number":11,"options":["when","after","since","before"]},{"number":12,"options":["kept","borrowed","withdrawn","released"]},{"number":13,"options":["Unless","Because","Until","Though"]},{"number":14,"options":["hide","express","raise","ease"]},{"number":15,"options":["analyzed","shared","displayed","stored"]},{"number":16,"options":["unsafe","unnatural","unclear","uncommon"]},{"number":17,"options":["choose","steal","benefit","return"]},{"number":18,"options":["consideration","manipulation","prevention","justification"]},{"number":19,"options":["call for","fight against","adapt to","cope with"]},{"number":20,"options":["chunk","chip","trail","path"]}],"sourcePages":[1,2]}'::jsonb,'published' from exam_sections s join exam_papers p on p.id=s.paper_id where p.year=2013 and s.type='cloze' on conflict(section_id) do update set content=excluded.content,status='published';
insert into private.cloze_keys(task_id,keys) select t.id,'[{"number":1,"answer":"A","explanation":"前文说“你可能会认为我们会迅速迈向无现金社会”，后文说“真正的无现金社会可能不会很快到来”，两者构成转折关系，因此选However。Moreover表递进，Therefore表因果，Otherwise表否则，均不符合逻辑。"},{"number":2,"answer":"A","explanation":"此处表示“预测已经存在了二十年”，around意为“大约、存在”，predictions have been around是固定搭配，表示“预测流传已久”。back、over、off与have been搭配均不能表达此意。"},{"number":3,"answer":"B","explanation":"《商业周刊》预测电子支付方式将“彻底改变货币本身的概念”，concept意为“概念”，与revolutionize the very...of money搭配合理。power（力量）、history（历史）、role（角色）均不能与“货币本身”构成合理搭配。"},{"number":4,"answer":"D","explanation":"此处表示《商业周刊》几年后“自我否定/反转”了其预测，reverse oneself意为“改变立场、自我否定”。reward（奖励）、resist（抵抗）、resume（恢复）均不符合语境。"},{"number":5,"answer":"C","explanation":"下文列举了多个阻碍无现金社会到来的因素，说明这一进程“缓慢”，slow意为“缓慢的”，符合语境。silent（沉默的）、sudden（突然的）、steady（稳定的）均不能准确表达“进展缓慢”之意。"},{"number":6,"answer":"B","explanation":"此处表示“有几个因素阻碍了纸币系统的消失”，work against意为“对……不利、阻碍”。work for（支持）、work with（与……合作）、work on（致力于）均不符合逻辑。"},{"number":7,"answer":"A","explanation":"建立计算机、读卡器和电信网络以使电子货币成为主导支付方式，成本很高，因此选expensive（昂贵的）。imaginative（富有想象力的）、sensitive（敏感的）、productive（多产的）均不能描述建立这些设施的特点。"},{"number":8,"answer":"A","explanation":"此处指使电子货币成为“主导的”支付形式，dominant意为“占主导地位的”。original（最初的）、temporary（临时的）、similar（相似的）均不能准确表达“主要/主导”之意。"},{"number":9,"answer":"B","explanation":"纸质支票的优势在于它们能“提供”收据，provide receipts意为“提供收据”。collect（收集）、copy（复制）、print（打印）均不能与receipts构成合理搭配，且不符合支票作为收据凭证的功能。"},{"number":10,"answer":"A","explanation":"许多消费者不愿意“放弃”收据，give up意为“放弃”。take over（接管）、bring back（带回）、pass down（传下去）均不符合“不愿意放弃收据”的语境。"},{"number":11,"answer":"D","explanation":"此处讲支票兑现和资金从出票人账户划出需要几天时间，即“在支票兑现之前”需要几天，所以用before。when表示当……时，after表示之后，since表示自从，均不符合时间先后逻辑。"},{"number":12,"answer":"C","explanation":"资金从出票人账户中被“取出、划走”，用withdrawn最准确，与from搭配表示从账户提取。kept保留、borrowed借入、released释放均不能准确描述资金从账户扣除的动作。"},{"number":13,"answer":"B","explanation":"前文说纸质支票有几天浮存期，后文说电子支付是即时的，因此“因为”电子支付即时，所以消除了浮存期，用Because引导原因状语从句。Unless除非、Until直到、Though虽然均不符合因果逻辑。"},{"number":14,"answer":"C","explanation":"电子支付方式可能“引起”安全和隐私担忧，raise concerns是固定搭配，意为引起担忧。hide隐藏、express表达、ease缓解均不能与concerns搭配表达引发忧虑之意。"},{"number":15,"answer":"D","explanation":"黑客进入计算机数据库并篡改“存储”在那里的信息，stored there作后置定语，表示存储的信息。analyzed分析、shared分享、displayed展示均不符合数据库信息被篡改的语境。"},{"number":16,"answer":"D","explanation":"此处说这种情况并非“不常见”，意味着黑客入侵是常见现象，因此 dishonest persons 可能访问账户。uncommon意为不寻常的，符合否定词not表达的“常见”之意。unsafe不安全、unnatural不自然、unclear不清楚均不合逻辑。"},{"number":17,"answer":"B","explanation":"不诚实的人可能进入电子支付系统的银行账户并“偷窃”他人的账户资金，steal from是固定搭配，意为从……偷窃。choose选择、benefit受益、return返回均不能与from someone else’s accounts搭配表达盗取之意。"},{"number":18,"answer":"C","explanation":"这种欺诈的“预防”并非易事，prevention of fraud意为欺诈预防，符合后文发展计算机科学应对安全问题的语境。consideration考虑、manipulation操纵、justification辩护均不能与fraud搭配表达防止欺诈之意。"},{"number":19,"answer":"D","explanation":"计算机科学的新领域正在发展以“应对”安全问题，cope with意为处理、应对，符合语境。call for要求、fight against对抗、adapt to适应均不如cope with能准确表达处理安全问题的含义。"},{"number":20,"answer":"C","explanation":"电子支付方式会留下包含大量个人数据的电子“痕迹”，electronic trail是固定搭配，意为电子痕迹。chunk块、chip芯片、path路径均不能与electronic搭配表达留下数据痕迹之意。"}]'::jsonb from cloze_tasks t join exam_sections s on s.id=t.section_id join exam_papers p on p.id=s.paper_id where p.year=2013 on conflict(task_id) do update set keys=excluded.keys;
insert into exam_sections(paper_id,type,item_count,position,status) select id,'cloze',1,1,'published' from exam_papers where year=2014 on conflict(paper_id,type) do update set item_count=1,status='published';
insert into cloze_tasks(section_id,content,status) select s.id,'{"year":2014,"directions":"Read the following text. Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET. (10 points)","paragraphs":["Thinner isn’t always better. A number of studies have {{1}} that normal-weight people are in fact at higher risk of some diseases compared to those who are overweight. And there are health conditions for which being overweight is actually {{2}} . For example, heavier women are less likely to develop calcium deficiency than thin women. {{3}} , among the elderly, being somewhat overweight is often an {{4}} of good health.","Of even greater {{5}} is the fact that obesity turns out to be very difficult to define. It is often defined {{6}} body mass index, or BMI. BMI {{7}} body mass divided by the square of height. An adult with a BMI of 18 to 25 is often considered to be normal weight. Between 25 and 30 is overweight. And over 30 is considered obese. Obesity, {{8}} , can be divided into moderately obese, severely obese, and very severely obese.","While such numerical standards seem {{9}} , they are not. Obesity is probably less a matter of weight than body fat. Some people with a high BMI are in fact extremely fit, {{10}} others with a low BMI may be in poor {{11}} . For example, many collegiate and professional football players {{12}} as obese, though their percentage body fat is low. Conversely, someone with a small frame may have high body fat but a {{13}} BMI.","Today we have a(n) {{14}} to label obesity as a disgrace. The overweight are sometimes {{15}} in the media with their faces covered. Stereotypes {{16}} with obesity include laziness, lack of will power, and lower prospects for success. Teachers, employers, and health professionals have been shown to harbor biases against the obese. {{17}} very young children tend to look down on the overweight, and teasing about body build has long been a problem in schools.","Negative attitudes toward obesity, {{18}} in health concerns, have stimulated a number of anti-obesity {{19}} . My own hospital system has banned sugary drinks from its facilities. Many employers have instituted weight loss and fitness initiatives. Michelle Obama has launched a high-visibility campaign {{20}} childhood obesity, even claiming that it represents our greatest national security threat."],"questions":[{"number":1,"options":["denied","concluded","doubted","ensured"]},{"number":2,"options":["protective","dangerous","sufficient","troublesome"]},{"number":3,"options":["Instead","However","Likewise","Therefore"]},{"number":4,"options":["indicator","objective","origin","example"]},{"number":5,"options":["impact","relevance","assistance","concern"]},{"number":6,"options":["in terms of","in case of","in favor of","in respects of"]},{"number":7,"options":["measures","determines","equals","modifies"]},{"number":8,"options":["in essence","in contrast","in turn","in part"]},{"number":9,"options":["complicated","conservative","variable","straightforward"]},{"number":10,"options":["so","while","since","unless"]},{"number":11,"options":["shape","spirit","balance","taste"]},{"number":12,"options":["start","qualify","retire","stay"]},{"number":13,"options":["strange","changeable","normal","constant"]},{"number":14,"options":["option","reason","opportunity","tendency"]},{"number":15,"options":["employed","pictured","imitated","monitored"]},{"number":16,"options":["compared","combined","settled","associated"]},{"number":17,"options":["Even","Still","Yet","Only"]},{"number":18,"options":["despised","corrected","ignored","grounded"]},{"number":19,"options":["discussions","businesses","policies","studies"]},{"number":20,"options":["for","against","with","without"]}],"sourcePages":[1,2]}'::jsonb,'published' from exam_sections s join exam_papers p on p.id=s.paper_id where p.year=2014 and s.type='cloze' on conflict(section_id) do update set content=excluded.content,status='published';
insert into private.cloze_keys(task_id,keys) select t.id,'[{"number":1,"answer":"B","explanation":"此处说多项研究“得出结论”：正常体重者患某些疾病风险反而更高。concluded 表示研究得出的结论，与 studies 搭配自然。denied“否认”、doubted“怀疑”与后文陈述的研究发现相悖；ensured“确保”不能接 that 从句表示研究结论。"},{"number":2,"answer":"A","explanation":"上文说超重者某些疾病风险更低，故对某些健康状况而言超重实际是“有保护作用的”。protective 与后文“较重女性较少缺钙”呼应。dangerous“危险的”、troublesome“麻烦的”与语境相反；sufficient“充足的”不表保护义。"},{"number":3,"answer":"C","explanation":"前句讲较重女性比瘦女性更少缺钙，本句讲老年人稍胖常是健康标志，两者是同类例证，故用 Likewise“同样地”。Instead 表替代，However 表转折，Therefore 表因果，均不符合并列举例的逻辑。"},{"number":4,"answer":"A","explanation":"句意为在老年人中，稍胖往往是健康的“标志”。indicator“指标、标志”与 of good health 搭配恰当。objective“目标”、origin“起源”语义不通；example“例子”虽可接 of，但“是健康的例子”不如“是健康的标志”贴合文意。"},{"number":5,"answer":"D","explanation":"前段谈超重未必有害，本段转入肥胖难以定义，这是“更令人担忧”的事。Of even greater concern 是固定表达，意为“更令人关切的是”。impact“影响”、relevance“相关性”、assistance“帮助”均不能构成这一固定搭配。"},{"number":6,"answer":"A","explanation":"句意为肥胖常“依据”体重指数来定义。in terms of 表示“按照、就……而言”，符合定义标准的语境。in case of“万一”、in favor of“支持”、in respects of 搭配不成立，均不能表示定义依据。"},{"number":7,"answer":"C","explanation":"此处解释 BMI 的计算方式：BMI“等于”体重除以身高的平方。equals 表示数值相等，符合公式定义。measures“测量”虽与指标相关，但不如 equals 准确表达等式关系；determines“决定”、modifies“修改”均不合逻辑。"},{"number":8,"answer":"C","explanation":"前文按 BMI 划分正常、超重、肥胖，本句接着说肥胖又可“进而”分为中度、重度等，in turn 表示递进、进一步。in essence“本质上”、in contrast“相反”、in part“部分地”都不符合层层细分的逻辑。"},{"number":9,"answer":"D","explanation":"such numerical standards 指上文 BMI 的数值划分，看起来“简单明了”，但后文说其实并非如此。straightforward 意为“简单明了的”，与 not 形成转折。complicated“复杂的”与 seem 后转折矛盾；conservative“保守的”、variable“可变的”不合文意。"},{"number":10,"answer":"B","explanation":"本句对比高 BMI 者可能很健康与低 BMI 者可能体质差，while 表对比“而”。so 表结果，since 表原因，unless 表条件，均不能体现两种情况的对照关系。"},{"number":11,"answer":"A","explanation":"空格所在句对比高BMI但身体健壮的人与低BMI但身体状况差的人，poor与shape搭配表示“身体状况不佳”，符合语境。spirit（精神）、balance（平衡）、taste（品味）均不能与poor构成“健康不佳”的固定表达，且与身体脂肪的讨论无关。"},{"number":12,"answer":"B","explanation":"本句举例说明高BMI者可能很健康，许多橄榄球运动员按BMI标准“符合”肥胖的界定，但体脂率低。qualify as意为“有资格被视为”，准确表达按标准归类。start/retire/stay as均不表示“符合标准而被归类”，与上下文逻辑不符。"},{"number":13,"answer":"C","explanation":"本句与上句形成对比：小骨架者体脂高但BMI却“正常”。normal与首段“正常体重者患病风险高”呼应，说明BMI数值可能误导。strange（奇怪）、changeable（多变）、constant（恒定）均不能准确描述BMI数值在正常范围内这一事实。"},{"number":14,"answer":"D","explanation":"本段讨论社会对肥胖的负面标签，tendency to label意为“倾向于给肥胖贴耻辱标签”，符合下文媒体、刻板印象等例证。option（选择）、reason（原因）、opportunity（机会）均不能与to label构成“有……倾向”的搭配，逻辑不通。"},{"number":15,"answer":"B","explanation":"媒体中超重者有时被“拍摄”时脸部被遮挡，pictured与in the media及with their faces covered搭配，描述媒体呈现方式。employed（雇用）、imitated（模仿）、monitored（监控）均不能准确表达媒体展示超重者形象这一语境。"},{"number":16,"answer":"D","explanation":"associated with obesity意为“与肥胖相关的刻板印象”，包括懒惰、缺乏意志力等，是固定搭配。compared（比较）、combined（结合）、settled（定居）均不能与stereotypes和with obesity构成“与……相关”的语义，不符合上下文。"},{"number":17,"answer":"A","explanation":"前文列举教师、雇主等成年人的偏见，本句进一步指出“甚至”幼儿也看不起超重者，Even表示递进强调，符合逻辑。Still（仍然）、Yet（然而）、Only（仅仅）均不能体现从成人到幼儿的递进关系，削弱了论证力度。"},{"number":18,"answer":"D","explanation":"grounded in health concerns意为“以健康担忧为基础”，说明对肥胖的负面态度源于健康考虑，并引发反肥胖政策。despised（鄙视）、corrected（纠正）、ignored（忽视）均不能与in health concerns搭配表达“基于”之意，逻辑不通。"},{"number":19,"answer":"C","explanation":"anti-obesity policies意为“反肥胖政策”，与下文医院禁售含糖饮料、雇主发起减肥计划等具体措施对应。discussions（讨论）、businesses（企业）、studies（研究）均不能概括这些机构层面的行动，且与stimulated搭配不当。"},{"number":20,"answer":"B","explanation":"campaign against childhood obesity意为“反对儿童肥胖的运动”，against表示对抗，与anti-obesity及下文“国家安全威胁”的立场一致。for（支持）、with（伴随）、without（没有）均不能表达米歇尔·奥巴马发起运动以对抗儿童肥胖的语义。"}]'::jsonb from cloze_tasks t join exam_sections s on s.id=t.section_id join exam_papers p on p.id=s.paper_id where p.year=2014 on conflict(task_id) do update set keys=excluded.keys;
insert into exam_sections(paper_id,type,item_count,position,status) select id,'cloze',1,1,'published' from exam_papers where year=2015 on conflict(paper_id,type) do update set item_count=1,status='published';
insert into cloze_tasks(section_id,content,status) select s.id,'{"year":2015,"directions":"Read the following text. Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET. (10 points)","paragraphs":["In our contemporary culture, the prospect of communicating with — or even looking at — a stranger is virtually unbearable. Everyone around us seems to agree by the way they cling to their phones, even without a {{1}} on a subway.","It’s a sad reality — our desire to avoid interacting with other human beings — because there’s {{2}} to be gained from talking to the stranger standing by you. But you wouldn’t know it, {{3}} into your phone. This universal protection sends the {{4}} : “please don’t approach me.”","What is it that makes us feel we need to hide {{5}} our screens?","One answer is fear, according to Jon Wortmann, an executive mental coach. We fear rejection, or that our innocent social advances will be {{6}} as “weird”. We fear we’ll be {{7}} . We fear we’ll be disruptive.","Strangers are inherently {{8}} to us, so we are more likely to feel {{9}} when communicating with them compared with our friends and acquaintances. To avoid this uneasiness, we {{10}} to our phones. “Phones become our security blanket,” Wortmann says. “They are our happy glasses that protect us from what we perceive is going to be more {{11}} .”","But once we rip off the band-aid, tuck our smartphones in our pockets and look up, it doesn’t {{12}} so bad. In one 2011 experiment, behavioral scientists Nicholas Epley and Juliana Schroeder asked commuters to do the unthinkable: Start a {{13}} . They had Chicago train commuters talk to their fellow {{14}} . “When Dr. Epley and Ms. Schroeder asked other people in the same train station to {{15}} how they would feel after talking to a stranger, the commuters thought their {{16}} would be more pleasant if they sat on their own,” The New York Times summarizes. Though the participants didn’t expect a positive experience, after they {{17}} with the experiment, “not a single person reported having been embarrassed.”","{{18}} , these commutes were reportedly more enjoyable compared with those without communication, which makes absolute sense, {{19}} human beings thrive off of social connections. It’s that {{20}} : Talking to strangers can make you feel connected."],"questions":[{"number":1,"options":["ticket","permit","signal","record"]},{"number":2,"options":["nothing","little","another","much"]},{"number":3,"options":["beaten","guided","plugged","brought"]},{"number":4,"options":["message","code","notice","sign"]},{"number":5,"options":["under","beyond","behind","from"]},{"number":6,"options":["misinterpreted","misapplied","misadjusted","mismatched"]},{"number":7,"options":["fired","judged","replaced","delayed"]},{"number":8,"options":["unreasonable","ungrateful","unconventional","unfamiliar"]},{"number":9,"options":["comfortable","anxious","confident","angry"]},{"number":10,"options":["attend","point","take","turn"]},{"number":11,"options":["dangerous","mysterious","violent","boring"]},{"number":12,"options":["hurt","resist","bend","decay"]},{"number":13,"options":["lecture","conversation","debate","negotiation"]},{"number":14,"options":["trainees","employees","researchers","passengers"]},{"number":15,"options":["reveal","choose","predict","design"]},{"number":16,"options":["voyage","flight","walk","ride"]},{"number":17,"options":["went through","did away","caught up","put up"]},{"number":18,"options":["In turn","In particular","In fact","In consequence"]},{"number":19,"options":["unless","since","if","whereas"]},{"number":20,"options":["funny","simple","logical","rare"]}],"sourcePages":[1,2]}'::jsonb,'published' from exam_sections s join exam_papers p on p.id=s.paper_id where p.year=2015 and s.type='cloze' on conflict(section_id) do update set content=excluded.content,status='published';
insert into private.cloze_keys(task_id,keys) select t.id,'[{"number":1,"answer":"C","explanation":"此处说人们紧握手机，即使地铁里没有信号也不放手。signal意为“信号”，符合手机使用语境。ticket“票”、permit“许可证”、record“记录”均与手机通讯信号无关，无法解释“cling to their phones”的原因。"},{"number":2,"answer":"D","explanation":"本句说与身旁陌生人交谈有“很多”收获，much与be gained搭配表示“可获得许多”。nothing和little与下文倡导交流的立场矛盾；another不能直接作be gained的主语，且语义不通。"},{"number":3,"answer":"C","explanation":"plugged into your phone意为“插在/埋头于手机里”，与上句cling to their phones呼应。beaten“被打”、guided“被引导”、brought“被带来”都不能与into your phone构成“专注于手机”的固定表达。"},{"number":4,"answer":"A","explanation":"send the message是固定搭配，意为“传递出……的信息”，后接“please don''t approach me”正是所传递的信息内容。code“代码”、notice“通知”、sign“标志”均不能与send the构成“传达信息”的常用搭配。"},{"number":5,"answer":"C","explanation":"hide behind our screens意为“躲在屏幕后面”，符合人们借手机屏幕回避社交的比喻。under“在……下面”、beyond“超出”、from“从”都不能与screens搭配表达“以屏幕为遮挡”之意。"},{"number":6,"answer":"A","explanation":"此处说我们担心主动的社交举动会被“误解”为怪异。misinterpreted as意为“被误解为”，与as“weird”搭配自然。misapplied“被误用”、misadjusted“被误调”、mismatched“被错配”均不能接as表示“被理解为”。"},{"number":7,"answer":"B","explanation":"本句列举社交恐惧：怕被拒绝、被误解为怪异、被“评判”。judged意为“被评判、被品头论足”，符合陌生人交往中的心理负担。fired“被解雇”、replaced“被取代”、delayed“被耽搁”与社交恐惧语境无关。"},{"number":8,"answer":"D","explanation":"陌生人本质上对我们来说是“不熟悉的”，unfamiliar to us意为“对我们不熟悉”，与下文compared with our friends形成对比。unreasonable“不合理的”、ungrateful“不感激的”、unconventional“非传统的”都不能解释陌生人引发的不安。"},{"number":9,"answer":"B","explanation":"因为陌生人不熟悉，与他们交流时我们更可能感到“焦虑不安”。anxious与后文uneasiness（不安）直接呼应。comfortable“舒适的”、confident“自信的”、angry“愤怒的”都不符合此处对比逻辑。"},{"number":10,"answer":"D","explanation":"turn to our phones意为“求助于手机、转向手机”，与上句“为避免不安”构成目的关系。attend to“处理”、point to“指向”、take to“开始从事/喜欢”均不能准确表达“借助手机逃避社交”之意。"},{"number":11,"answer":"A","explanation":"空格所在句说手机是“快乐眼镜”，保护我们免受我们感知中更{{11}}的东西。前文反复讲恐惧：怕被拒绝、被误解、被评判，故此处应填 dangerous“危险的”，与 protect...from 搭配，指我们主观上觉得陌生人可能带来危险。mysterious 虽可形容陌生人，但不含威胁感；violent 过于具体；boring 与“保护”逻辑相反。"},{"number":12,"answer":"A","explanation":"句意为：一旦撕掉创可贴、把手机塞进口袋抬起头，事情并没有那么糟。it doesn''t hurt so bad 是口语表达，意为“没那么难受/没那么糟”，hurt 与上文的 fear、uneasiness 形成呼应。resist“抵抗”、bend“弯曲”、decay“腐烂”均无法与 it doesn''t...so bad 构成“感觉没那么糟”的语义。"},{"number":13,"answer":"B","explanation":"实验要求通勤者做“不可想象的事”：开始一段{{13}}。后文明确说让他们与同车乘客交谈，故填 conversation“交谈”。lecture“讲座”、debate“辩论”、negotiation“谈判”都指正式或对抗性的言语活动，与陌生人闲聊的语境不符，也无法与 talk to 对应。"},{"number":14,"answer":"D","explanation":"实验对象是芝加哥火车上的通勤者，让他们与同车的{{14}}交谈。fellow passengers 意为“同车乘客”，与前文 commuters、train 完全吻合。trainees“受训者”、employees“雇员”、researchers“研究者”均不能概括火车上被搭话的陌生人，且与 commuters 身份不对应。"},{"number":15,"answer":"C","explanation":"研究者请同一车站的其他人{{15}}与陌生人交谈后的感受。predict“预测”与后文“通勤者以为独自坐着会更愉快”以及“参与者没料到会有积极体验”相呼应，说明这是事前预判。reveal“揭示”是事后公开，choose“选择”、design“设计”都不能表达对感受的预先估计。"},{"number":16,"answer":"D","explanation":"通勤者认为，如果独自坐着，他们的{{16}}会更愉快。此处指乘坐火车这段行程，ride 可指乘车/乘火车的旅程，与 train commuters 搭配自然。voyage 多指海上航行，flight 指航班，walk 指步行，均不符合火车通勤的语境。"},{"number":17,"answer":"A","explanation":"虽然参与者没料到会有积极体验，但在他们{{17}}实验之后，“没有一个人报告感到尴尬”。go through with 意为“完成、经历（某事）”，符合做完实验的语义。do away with“废除”、catch up with“赶上”、put up with“忍受”均不能表示完成实验。"},{"number":18,"answer":"C","explanation":"前文说没人感到尴尬，此处接着说这些通勤据报告比不交流更愉快，语意上是进一步确认甚至加强，故用 In fact“事实上”。In turn“依次、转而”表因果连锁，In particular“尤其”表举例，In consequence“因此”表结果，均不如 In fact 贴合递进确认的逻辑。"},{"number":19,"answer":"B","explanation":"空格前后为因果关系：这完全说得通，{{19}}人类本就靠社会联系兴旺发展。since 意为“因为、既然”，引导原因状语从句，正好解释为何交流更愉快。unless“除非”、if“如果”表条件，whereas“然而”表对比，都无法建立这里的因果解释。"},{"number":20,"answer":"B","explanation":"末句总结：道理就这么{{20}}——与陌生人交谈能让你感到有联系。simple 意为“简单的”，呼应前文“完全说得通”，强调道理朴素明了。funny“有趣的”、logical“合乎逻辑的”虽不无道理，但不如 simple 与全文“其实没那么复杂”的收束语气契合；rare 则与主旨相反。"}]'::jsonb from cloze_tasks t join exam_sections s on s.id=t.section_id join exam_papers p on p.id=s.paper_id where p.year=2015 on conflict(task_id) do update set keys=excluded.keys;
insert into exam_sections(paper_id,type,item_count,position,status) select id,'cloze',1,1,'published' from exam_papers where year=2016 on conflict(paper_id,type) do update set item_count=1,status='published';
insert into cloze_tasks(section_id,content,status) select s.id,'{"year":2016,"directions":"Read the following text. Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET. (10 points)","paragraphs":["Happy people work differently. They’re more productive, more creative, and willing to take greater risks. And new research suggests that happiness might influence {{1}} firms work, too.","Companies located in places with happier people invest more, according to a recent research paper. {{2}} , firms in happy places spend more on R&D (research and development). That’s because happiness is linked to the kind of longer-term thinking {{3}} for making investments for the future.","The researchers wanted to know if the {{4}} and inclination for risk-taking that come with happiness would {{5}} the way companies invested. So they compared U.S. cities’ average happiness {{6}} by Gallup polling with the investment activity of publicly traded firms in those areas.","{{7}} enough, firms’ investment and R&D intensity were correlated with the happiness of the area in which they were {{8}} . But is it really happiness that’s linked to investment, or could something else about happier cities {{9}} why firms there spend more on R&D? To find out, the researchers controlled for various {{10}} that might make firms more likely to invest — like size, industry, and sales — and for indicators that a place was {{11}} to live in, like growth in wages or population. The link between happiness and investment generally {{12}} even after accounting for these things.","The correlation between happiness and investment was particularly strong for younger firms, which the authors {{13}} to “less codified decision making process” and the possible presence of “younger and less {{14}} managers who are more likely to be influenced by sentiment.” The relationship was {{15}} stronger in places where happiness was spread more {{16}} . Firms seem to invest more in places where most people are relatively happy, rather than in places with happiness inequality.","{{17}} this doesn’t prove that happiness causes firms to invest more or to take a longer-term view, the authors believe it at least {{18}} at that possibility. It’s not hard to imagine that local culture and sentiment would help {{19}} how executives think about the future. “It surely seems plausible that happy people would be more forward-thinking and creative and {{20}} R&D more than the average,” said one researcher."],"questions":[{"number":1,"options":["why","where","how","when"]},{"number":2,"options":["In return","In particular","In contrast","In conclusion"]},{"number":3,"options":["sufficient","famous","perfect","necessary"]},{"number":4,"options":["individualism","modernism","optimism","realism"]},{"number":5,"options":["echo","miss","spoil","change"]},{"number":6,"options":["imagined","measured","invented","assumed"]},{"number":7,"options":["Sure","Odd","Unfortunate","Often"]},{"number":8,"options":["advertised","divided","overtaxed","headquartered"]},{"number":9,"options":["explain","overstate","summarize","emphasize"]},{"number":10,"options":["stages","factors","levels","methods"]},{"number":11,"options":["desirable","sociable","reputable","reliable"]},{"number":12,"options":["resumed","held","emerged","broke"]},{"number":13,"options":["attribute","assign","transfer","compare"]},{"number":14,"options":["serious","civilized","ambitious","experienced"]},{"number":15,"options":["thus","instead","also","never"]},{"number":16,"options":["rapidly","regularly","directly","equally"]},{"number":17,"options":["After","Until","While","Since"]},{"number":18,"options":["arrives","jumps","hints","strikes"]},{"number":19,"options":["shape","rediscover","simplify","share"]},{"number":20,"options":["pray for","lean towards","give away","send out"]}],"sourcePages":[1,2]}'::jsonb,'published' from exam_sections s join exam_papers p on p.id=s.paper_id where p.year=2016 and s.type='cloze' on conflict(section_id) do update set content=excluded.content,status='published';
insert into private.cloze_keys(task_id,keys) select t.id,'[{"number":1,"answer":"C","explanation":"空格所在句意为“新研究表明幸福也可能影响公司如何运作”，how firms work 表示“公司如何运作”，与上文“happy people work differently”形成呼应。why表原因、where表地点、when表时间，均无法与work搭配表达“运作方式”，故排除。"},{"number":2,"answer":"B","explanation":"上文说幸福地方的公司投资更多，本句进一步具体指出“这些公司研发支出更多”，是前句的细化举例，故用In particular（尤其、特别是）。In return表回报，In contrast表对比，In conclusion表总结，均不符合递进举例的逻辑。"},{"number":3,"answer":"D","explanation":"此处说幸福与“为未来投资所必需的那种长期思维”相关，necessary for 表示“对……是必要的”，符合语境。sufficient（充足）、famous（著名）、perfect（完美）都不能与for making investments搭配表达“投资所需”的含义。"},{"number":4,"answer":"C","explanation":"空格与inclination并列，指随幸福而来的“乐观和冒险倾向”，optimism（乐观）与happiness语义一致。individualism（个人主义）、modernism（现代主义）、realism（现实主义）均与幸福、冒险倾向无直接关联，不能构成并列。"},{"number":5,"answer":"D","explanation":"句意为研究者想知道乐观和冒险倾向是否会“改变”公司的投资方式，change the way 是固定搭配。echo（回声、附和）、miss（错过）、spoil（破坏）都不能与the way companies invested搭配表达“改变方式”之意。"},{"number":6,"answer":"B","explanation":"此处指盖洛普民调“测量”出的城市平均幸福度，measured by Gallup polling 表示“由盖洛普民调测量”。imagined（想象）、invented（发明）、assumed（假定）都不符合民调实际测量数据的语境。"},{"number":7,"answer":"A","explanation":"Sure enough 意为“果然、不出所料”，承接上文假设，引出研究确实发现投资与幸福相关，符合逻辑。Odd（奇怪）、Unfortunate（不幸）、Often（经常）都不能独立构成这种承上启下的固定表达。"},{"number":8,"answer":"D","explanation":"此处指公司“总部设在”那些地区，headquartered 意为“总部位于”，与firms和areas搭配自然。advertised（做广告）、divided（分割）、overtaxed（过度征税）均不能表达公司所在地的含义。"},{"number":9,"answer":"A","explanation":"句意为“或者幸福城市还有其他因素可以解释为何那里公司研发支出更多”，explain why 表示“解释为什么”。overstate（夸大）、summarize（总结）、emphasize（强调）都不能与why从句搭配表达“解释原因”。"},{"number":10,"answer":"B","explanation":"研究者控制的是“可能使公司更愿意投资的各种因素”，factors 意为“因素”，与controlled for搭配。stages（阶段）、levels（水平）、methods（方法）都不能概括规模、行业、销售这类影响投资的变量。"},{"number":11,"answer":"A","explanation":"此处列举使一个地方“宜居”的指标，如工资或人口增长。desirable意为“令人向往的、宜居的”，符合语境。sociable“好交际的”、reputable“有声望的”、reliable“可靠的”均不能修饰“居住地”的适宜性。"},{"number":12,"answer":"B","explanation":"句意：在控制了这些因素后，幸福与投资之间的关联总体上依然成立。held是hold的过去式，意为“保持、有效”，符合逻辑。resumed“恢复”、emerged“出现”、broke“打破”均与“关联持续存在”的语义不符。"},{"number":13,"answer":"A","explanation":"作者将年轻公司中更强的相关性归因于“不太成文的决策过程”。attribute...to...意为“把……归因于……”，是固定搭配。assign“分配”、transfer“转移”、compare“比较”均不能与to构成此义。"},{"number":14,"answer":"D","explanation":"此处描述年轻公司中可能存在的“更年轻且经验更少的管理者”。experienced意为“有经验的”，与less搭配表示“经验较少”，符合上下文。serious“严肃的”、civilized“文明的”、ambitious“有雄心的”均不能与less构成“经验不足”之意。"},{"number":15,"answer":"C","explanation":"前文说年轻公司中关联更强，此处进一步说在幸福分布更均匀的地方关联也更强。also表示“也”，符合递进逻辑。thus“因此”、instead“相反”、never“从不”均不合逻辑。"},{"number":16,"answer":"D","explanation":"后文解释为“大多数人相对幸福的地方，而非幸福不平等的地方”，因此此处指幸福分布更“平等”。equally意为“平等地、均匀地”，符合语境。rapidly“快速地”、regularly“有规律地”、directly“直接地”均不能与spread搭配表达分布均匀。"},{"number":17,"answer":"C","explanation":"此处表示让步：虽然这不能证明幸福导致公司增加投资，但作者认为至少暗示了这种可能性。While意为“虽然”，引导让步状语从句。After“在……之后”、Until“直到”、Since“自从/因为”均不合逻辑。"},{"number":18,"answer":"C","explanation":"句意：作者认为这至少“暗示”了那种可能性。hints at意为“暗示”，符合语境。arrives at“到达”、jumps at“扑向”、strikes at“打击”均不能与possibility搭配表达“暗示可能性”。"},{"number":19,"answer":"A","explanation":"句意：不难想象当地文化和情绪会帮助“塑造”高管对未来的看法。shape意为“塑造、影响”，符合搭配。rediscover“重新发现”、simplify“简化”、share“分享”均不能与how executives think about the future搭配。"},{"number":20,"answer":"B","explanation":"句意：幸福的人更向前看、更有创造力，并且比普通人更“倾向于”研发。lean towards意为“倾向于”，符合逻辑。pray for“祈求”、give away“赠送”、send out“发出”均不能表达“倾向于研发”之意。"}]'::jsonb from cloze_tasks t join exam_sections s on s.id=t.section_id join exam_papers p on p.id=s.paper_id where p.year=2016 on conflict(task_id) do update set keys=excluded.keys;
insert into exam_sections(paper_id,type,item_count,position,status) select id,'cloze',1,1,'published' from exam_papers where year=2017 on conflict(paper_id,type) do update set item_count=1,status='published';
insert into cloze_tasks(section_id,content,status) select s.id,'{"year":2017,"directions":"Read the following text. Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET. (10 points)","paragraphs":["People have speculated for centuries about a future without work. Today is no different, with academics, writers, and activists once again {{1}} that technology is replacing human workers. Some imagine that the coming work-free world will be defined by {{2}} : A few wealthy people will own all the capital, and the masses will struggle in an impoverished wasteland.","A different and not mutually exclusive {{3}} holds that the future will be a wasteland of a different sort, one {{4}} by purposelessness: Without jobs to give their lives {{5}} , people will simply become lazy and depressed. {{6}} , today’s unemployed don’t seem to be having a great time. One Gallup poll found that 20 percent of Americans who have been unemployed for at least a year report having depression, double the rate for {{7}} Americans. Also, some research suggests that the {{8}} for rising rates of mortality, mental-health problems, and addiction {{9}} poorly-educated, middle-aged people is a shortage of well-paid jobs. Perhaps this is why many {{10}} the agonizing dullness of a jobless future.","But it doesn’t {{11}} follow from findings like these that a world without work would be filled with unease. Such visions are based on the {{12}} of being unemployed in a society built on the concept of employment. In the {{13}} of work, a society designed with other ends in mind could {{14}} strikingly different circumstances for the future of labor and leisure. Today, the {{15}} of work may be a bit overblown. “Many jobs are boring, degrading, unhealthy, and a waste of human potential,” says John Danaher, a lecturer at the National University of Ireland in Galway.","These days, because leisure time is relatively {{16}} for most workers, people use their free time to counterbalance the intellectual and emotional {{17}} of their jobs. “When I come home from a hard day’s work, I often feel {{18}} ,” Danaher says, adding, “In a world in which I don’t have to work, I might feel rather different” — perhaps different enough to throw himself {{19}} a hobby or a passion project with the intensity usually reserved for {{20}} matters."],"questions":[{"number":1,"options":["boasting","denying","warning","ensuring"]},{"number":2,"options":["inequality","instability","unreliability","uncertainty"]},{"number":3,"options":["policy","guideline","resolution","prediction"]},{"number":4,"options":["characterized","divided","balanced","measured"]},{"number":5,"options":["wisdom","meaning","glory","freedom"]},{"number":6,"options":["Instead","Indeed","Thus","Nevertheless"]},{"number":7,"options":["rich","urban","working","educated"]},{"number":8,"options":["explanation","requirement","compensation","substitute"]},{"number":9,"options":["under","beyond","alongside","among"]},{"number":10,"options":["leave behind","make up","worry about","set aside"]},{"number":11,"options":["statistically","occasionally","necessarily","economically"]},{"number":12,"options":["chances","downsides","benefits","principles"]},{"number":13,"options":["absence","height","face","course"]},{"number":14,"options":["disturb","restore","exclude","yield"]},{"number":15,"options":["model","practice","virtue","hardship"]},{"number":16,"options":["tricky","lengthy","mysterious","scarce"]},{"number":17,"options":["demands","standards","qualities","threats"]},{"number":18,"options":["ignored","tired","confused","starved"]},{"number":19,"options":["off","against","behind","into"]},{"number":20,"options":["technological","professional","educational","interpersonal"]}],"sourcePages":[1,2]}'::jsonb,'published' from exam_sections s join exam_papers p on p.id=s.paper_id where p.year=2017 and s.type='cloze' on conflict(section_id) do update set content=excluded.content,status='published';
insert into private.cloze_keys(task_id,keys) select t.id,'[{"number":1,"answer":"C","explanation":"此处需填入动词，表示学者、作家和活动家再次发出警告。warning意为“警告”，符合上下文“技术正在取代人类工人”的警示语气。boasting（吹嘘）与语境不符；denying（否认）与后文“技术取代工人”的观点矛盾；ensuring（确保）语义不通。"},{"number":2,"answer":"A","explanation":"冒号后解释“少数富人拥有所有资本，大众在贫困荒原中挣扎”，这描述的是财富分配不均，即inequality（不平等）。instability（不稳定）、unreliability（不可靠）、uncertainty（不确定性）均不能准确概括贫富分化的现象。"},{"number":3,"answer":"D","explanation":"此处指另一种“预测”，与第一段“人们推测未来”呼应。prediction意为“预测”，符合语境。policy（政策）、guideline（指导方针）、resolution（决议）均不能与“holds that”搭配表示一种观点。"},{"number":4,"answer":"A","explanation":"此处修饰“荒原”，表示其特点是“无目的性”。characterized by意为“以……为特征”，符合语法和语义。divided（划分）、balanced（平衡）、measured（测量）均不能与by搭配表达“具有……特征”。"},{"number":5,"answer":"B","explanation":"此处指工作赋予生活意义。give meaning to是固定搭配，意为“赋予意义”。wisdom（智慧）、glory（荣耀）、freedom（自由）均不能与give...to搭配表达“赋予生活意义”的常见含义。"},{"number":6,"answer":"B","explanation":"前文说没有工作人会变懒和抑郁，后文用调查数据证明今天失业者确实状态不佳，此处需表示“确实”的副词。Indeed意为“确实”，用于强调。Instead（相反）、Thus（因此）、Nevertheless（然而）均不符合逻辑关系。"},{"number":7,"answer":"C","explanation":"此处对比失业美国人与有工作的美国人。working Americans意为“在职美国人”，与unemployed形成对照。rich（富裕的）、urban（城市的）、educated（受过教育的）均不能与unemployed形成直接对比。"},{"number":8,"answer":"A","explanation":"此处指对死亡率、心理健康问题和成瘾率上升的“解释”。explanation意为“解释”，符合语境。requirement（要求）、compensation（补偿）、substitute（替代品）均不能与for搭配表示“对……的解释”。"},{"number":9,"answer":"D","explanation":"此处表示“在受教育程度低的中年人中”，among意为“在……之中”，符合语境。under（在……下）、beyond（超出）、alongside（与……一起）均不能准确表达人群范围。"},{"number":10,"answer":"C","explanation":"此处指许多人“担心”无工作未来的无聊。worry about意为“担心”，符合上下文对未来的忧虑。leave behind（留下）、make up（组成）、set aside（搁置）均不能表达担忧之意。"},{"number":11,"answer":"C","explanation":"necessarily与前面的doesn''t构成否定搭配，表示“并不必然”，即这些发现不能必然推出无工作的世界会充满不安。statistically（统计上）、occasionally（偶尔）、economically（经济上）均无法与follow from构成“必然推出”的逻辑关系，语义不通。"},{"number":12,"answer":"B","explanation":"downsides指“弊端、负面”，与后文being unemployed in a society built on employment呼应，说明这些悲观想象基于失业的负面处境。chances（机会）、benefits（好处）与语境相反；principles（原则）与“失业”搭配不当。"},{"number":13,"answer":"A","explanation":"In the absence of work是固定搭配，意为“在没有工作的情况下”，与上句“基于就业社会中的失业”形成对照。height（高度）、face（面对）、course（过程）均不能构成“absence of work”这一表达，逻辑也不符。"},{"number":14,"answer":"D","explanation":"yield意为“产生、带来”，搭配yield strikingly different circumstances，表示一个以其他目标设计的社会会带来截然不同的境况。disturb（打扰）、restore（恢复）、exclude（排除）均不能与circumstances构成“带来境况”的合理搭配。"},{"number":15,"answer":"C","explanation":"virtue of work指“工作的优点/价值”，与后文“许多工作无聊、有辱人格”形成转折，说明今天工作的价值可能被高估。model（模式）、practice（做法）、hardship（艰难）均不能与overblown搭配表达“价值被夸大”。"},{"number":16,"answer":"D","explanation":"scarce意为“稀缺的”，说明对多数工人而言闲暇时间相对稀少，因此人们用空闲时间来平衡工作的消耗。tricky（棘手的）、lengthy（冗长的）、mysterious（神秘的）均不能说明闲暇时间少这一前提，与后文逻辑不符。"},{"number":17,"answer":"A","explanation":"demands指“要求、需求”，与intellectual and emotional搭配，表示工作的智力和情感要求，人们用闲暇来抵消这些要求。standards（标准）、qualities（品质）、threats（威胁）与counterbalance的搭配均不如demands贴切。"},{"number":18,"answer":"B","explanation":"tired意为“疲惫的”，与hard day''s work直接呼应，说明下班回家后常感疲惫。ignored（被忽视）、confused（困惑）、starved（饥饿）均不能由“辛苦工作一天”自然推出，语境不符。"},{"number":19,"answer":"D","explanation":"throw oneself into是固定搭配，意为“投身于”，表示全身心投入爱好或热情项目。throw off（摆脱）、throw against（反对）、throw behind（支持）均不能与a hobby构成“投身于”的语义。"},{"number":20,"answer":"B","explanation":"professional matters指“职业/专业事务”，与hobby或passion project形成对比，说明通常只把那种强度留给职业事务。technological（技术的）、educational（教育的）、interpersonal（人际的）均不能与matters搭配表达“职业事务”这一对比对象。"}]'::jsonb from cloze_tasks t join exam_sections s on s.id=t.section_id join exam_papers p on p.id=s.paper_id where p.year=2017 on conflict(task_id) do update set keys=excluded.keys;
insert into exam_sections(paper_id,type,item_count,position,status) select id,'cloze',1,1,'published' from exam_papers where year=2018 on conflict(paper_id,type) do update set item_count=1,status='published';
insert into cloze_tasks(section_id,content,status) select s.id,'{"year":2018,"directions":"Read the following text. Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET. (10 points)","paragraphs":["Why do people read negative Internet comments and do other things that will obviously be painful? Because humans have an inherent need to {{1}} uncertainty, according to a recent study in Psychological Science . The new research reveals that the need to know is so strong that people will {{2}} to satisfy their curiosity even when it is clear the answer will {{3}} .","In a series of four experiments, behavioral scientists at the University of Chicago and the Wisconsin School of Business tested students’ willingness to {{4}} themselves to unpleasant stimuli in an effort to satisfy curiosity. For one {{5}} , each participant was shown a pile of pens that the researcher claimed were from a previous experiment. The twist? Half of the pens would {{6}} an electric shock when clicked.","Twenty-seven students were told which pens were electrified; another twenty-seven were told only that some were electrified. {{7}} left alone in the room, the students who did not know which ones would shock them clicked more pens and incurred more shocks than the students who knew what would {{8}} . Subsequent experiments reproduced this effect with other stimuli, {{9}} the sound of fingernails on a chalkboard and photographs of disgusting insects.","The drive to {{10}} is deeply rooted in humans, much the same as the basic drives for {{11}} or shelter, says Christopher Hsee of the University of Chicago. Curiosity is often considered a good instinct — it can {{12}} new scientific advances, for instance — but sometimes such {{13}} can backfire. The insight that curiosity can drive you to do {{14}} things is a profound one.","Unhealthy curiosity is possible to {{15}} , however. In a final experiment, participants who were encouraged to {{16}} how they would feel after viewing an unpleasant picture were less likely to {{17}} to see such an image. These results suggest that imagining the {{18}} of following through on one’s curiosity ahead of time can help determine {{19}} it is worth the endeavor. “Thinking about long-term {{20}} is key to reducing the possible negative effects of curiosity,” Hsee says. In other words, don’t read online comments."],"questions":[{"number":1,"options":["ignore","protect","discuss","resolve"]},{"number":2,"options":["refuse","seek","wait","regret"]},{"number":3,"options":["rise","last","hurt","mislead"]},{"number":4,"options":["alert","expose","tie","treat"]},{"number":5,"options":["trial","message","review","concept"]},{"number":6,"options":["remove","deliver","weaken","interrupt"]},{"number":7,"options":["Unless","If","When","Though"]},{"number":8,"options":["change","continue","disappear","happen"]},{"number":9,"options":["such as","rather than","regardless of","owing to"]},{"number":10,"options":["disagree","forgive","discover","forget"]},{"number":11,"options":["pay","food","marriage","schooling"]},{"number":12,"options":["begin with","rest on","lead to","learn from"]},{"number":13,"options":["inquiry","withdrawal","persistence","diligence"]},{"number":14,"options":["self-deceptive","self-reliant","self-evident","self-destructive"]},{"number":15,"options":["trace","define","replace","resist"]},{"number":16,"options":["conceal","overlook","design","predict"]},{"number":17,"options":["choose","remember","promise","pretend"]},{"number":18,"options":["relief","outcome","plan","duty"]},{"number":19,"options":["how","why","where","whether"]},{"number":20,"options":["limitations","investments","consequences","strategies"]}],"sourcePages":[1,2]}'::jsonb,'published' from exam_sections s join exam_papers p on p.id=s.paper_id where p.year=2018 and s.type='cloze' on conflict(section_id) do update set content=excluded.content,status='published';
insert into private.cloze_keys(task_id,keys) select t.id,'[{"number":1,"answer":"D","explanation":"空格前说人们会读负面评论等明显痛苦的事，后文解释是因为人有消除不确定性的内在需求。resolve uncertainty意为“消除不确定性”，与need to know呼应。ignore“忽视”与好奇心相悖；protect“保护”和discuss“讨论”均不能与uncertainty构成合理搭配。"},{"number":2,"answer":"B","explanation":"前文说求知欲极强，此处表示人们会“寻求”满足好奇心，seek to do意为“试图做某事”。refuse“拒绝”与求知欲矛盾；wait“等待”不能体现主动追求；regret“后悔”语义不通。"},{"number":3,"answer":"C","explanation":"即使明知答案会“伤害”自己，人们仍会去满足好奇心，与首段painful及后文electric shock呼应。rise“上升”、last“持续”与答案性质无关；mislead“误导”虽可能，但不如hurt直接对应痛苦体验。"},{"number":4,"answer":"B","explanation":"实验测试学生是否愿意让自己“接触”不愉快刺激以满足好奇心，expose oneself to意为“使自己接触”。alert“警觉”、tie“捆绑”、treat“对待”均不能与themselves to unpleasant stimuli构成自然搭配。"},{"number":5,"answer":"A","explanation":"前文说进行了一系列实验，此处指其中一个“试验”，for one trial意为“在一个试验中”。message“信息”、review“评论”、concept“概念”均不符合实验语境。"},{"number":6,"answer":"B","explanation":"一半的笔被点击时会“发出”电击，deliver an electric shock为固定搭配，意为“释放电击”。remove“移除”、weaken“削弱”、interrupt“打断”均不能与electric shock搭配表达释放电击之意。"},{"number":7,"answer":"C","explanation":"此处表示“当”学生被单独留在房间里时，when引导时间状语从句。unless“除非”、if“如果”表条件，though“虽然”表让步，均不符合此处描述实验过程的逻辑。"},{"number":8,"answer":"D","explanation":"知道会发生什么的学生点击更少，what would happen意为“会发生什么”，与前半句which pens were electrified对应。change“改变”、continue“继续”、disappear“消失”均不能概括电击这一预期事件。"},{"number":9,"answer":"A","explanation":"后文列举指甲刮黑板声和恶心昆虫照片，是对other stimuli的举例，such as“例如”符合逻辑。rather than“而不是”、regardless of“不管”、owing to“由于”均不能引出例证。"},{"number":10,"answer":"C","explanation":"本段讨论好奇心驱动力，the drive to discover意为“发现的驱动力”，与curiosity同义复现。disagree“不同意”、forgive“原谅”、forget“忘记”均与好奇心主题无关。"},{"number":11,"answer":"B","explanation":"此处将好奇心与“食物或住所”这类基本驱动力并列，food与shelter构成生存需求的常见搭配。pay、marriage、schooling都不是与shelter并列的基本生存需求，且与deeply rooted in humans的语境不符。"},{"number":12,"answer":"C","explanation":"破折号后举例说明好奇心能“带来”新科学进步，lead to表示导致、带来，符合因果逻辑。begin with（以…开始）、rest on（依赖）、learn from（从…学习）都不能表达好奇心促成科学进步这一结果关系。"},{"number":13,"answer":"A","explanation":"such指代前文的curiosity，inquiry意为探究、询问，与好奇心同义复现，作主语表示这种探究有时会适得其反。withdrawal（退缩）、persistence（坚持）、diligence（勤奋）均不能回指curiosity。"},{"number":14,"answer":"D","explanation":"本段说好奇心有时会backfire，故此处指好奇心会驱使你做“自我毁灭的”事情，self-destructive与backfire及后文负面效果呼应。self-deceptive（自欺的）、self-reliant（自立的）、self-evident（不言而喻的）都不符合语境。"},{"number":15,"answer":"D","explanation":"however转折，后文实验表明不良好奇心可以被抑制，resist意为抵制、抵抗，与possible to搭配表示“可以抵制”。trace（追踪）、define（定义）、replace（替代）都不能与unhealthy curiosity构成合理搭配。"},{"number":16,"answer":"D","explanation":"实验中鼓励参与者“预测”自己看 unpleasant picture 后的感受，predict与后文imagining...ahead of time及long-term consequences呼应。conceal（隐藏）、overlook（忽视）、design（设计）都不符合预先设想感受的语境。"},{"number":17,"answer":"A","explanation":"能预测负面感受的人更不可能“选择”去看这类图片，choose to do表示选择做某事，与less likely to搭配自然。remember、promise、pretend与see such an image搭配均不能表达主动选择的行为。"},{"number":18,"answer":"B","explanation":"imagining the outcome of following through on one''s curiosity指预想践行好奇心的“结果”，outcome与后文determine whether it is worth the endeavor逻辑一致。relief（宽慰）、plan（计划）、duty（责任）都不符合预想后果的语境。"},{"number":19,"answer":"D","explanation":"determine whether it is worth the endeavor表示判断是否值得尝试，whether引导宾语从句表“是否”，与ahead of time预判的逻辑吻合。how、why、where都不能与it is worth the endeavor构成“是否值得”的判断。"},{"number":20,"answer":"C","explanation":"Hsee总结思考长期“后果”是减少好奇心负面影响的关键，consequences与上文的outcome及negative effects呼应。limitations（局限）、investments（投资）、strategies（策略）都不能与long-term搭配表达长期后果。"}]'::jsonb from cloze_tasks t join exam_sections s on s.id=t.section_id join exam_papers p on p.id=s.paper_id where p.year=2018 on conflict(task_id) do update set keys=excluded.keys;
insert into exam_sections(paper_id,type,item_count,position,status) select id,'cloze',1,1,'published' from exam_papers where year=2019 on conflict(paper_id,type) do update set item_count=1,status='published';
insert into cloze_tasks(section_id,content,status) select s.id,'{"year":2019,"directions":"Read the following text. Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET. (10 points)","paragraphs":["Weighing yourself regularly is a wonderful way to stay aware of any significant weight fluctuations. {{1}} , when done too often, this habit can sometimes hurt more than it {{2}} .","As for me, weighing myself every day caused me to shift my focus from being generally healthy and physically active to focusing {{3}} on the scale. That was bad to my overall fitness goals. I had gained weight in the form of muscle mass, but thinking only of {{4}} the number on the scale, I altered my training program. That conflicted with how I needed to train to {{5}} my goals.","I also found that weighing myself daily did not provide an accurate {{6}} of the hard work and progress I was making in the gym. It takes about three weeks to a month to notice any significant changes in your weight {{7}} altering your training program. The most {{8}} changes will be observed in skill level, strength and inches lost.","For these {{9}} , I stopped weighing myself every day and switched to a bimonthly weighing schedule {{10}} . Since weight loss is not my goal, it is less important for me to {{11}} my weight each week Weighing every other week allows me to observe and {{12}} any significant weight changes. That tells me whether I need to {{13}} my training program.","I use my bimonthly weigh-in {{14}} to get information about my nutrition as well. If my training intensity remains the same, but I''m constantly {{15}} and dropping weight, this is a {{16}} that I need to increase my daily caloric intake.","The {{17}} to stop weighing myself every day has done wonders for my overall health, fitness and well-being. I''m experiencing increased zeal for working out since I no longer carry the burden of a {{18}} morning weigh-in. I''ve also experienced greater success in achieving my specific fitness goals, {{19}} I''m training according to those goals, not the numbers on a scale.","Rather than {{20}} over the scale, turn your focus to how you look, feel, how your clothes fit and your overall energy level."],"questions":[{"number":1,"options":["However","Therefore","Otherwise","Besides"]},{"number":2,"options":["cares","helps","warns","reduces"]},{"number":3,"options":["initially","occasionally","solely","formally"]},{"number":4,"options":["recording","explaining","lowering","accepting"]},{"number":5,"options":["reach","set","review","modify"]},{"number":6,"options":["definition","distribution","depiction","prediction"]},{"number":7,"options":["regardless of","due to","aside from","along with"]},{"number":8,"options":["immediate","rigid","precise","orderly"]},{"number":9,"options":["claims","judgments","methods","reasons"]},{"number":10,"options":["though","instead","again","indeed"]},{"number":11,"options":["report","overlook","track","conceal"]},{"number":12,"options":["account for","approve of","hold onto","depend on"]},{"number":13,"options":["prepare","share","confirm","adjust"]},{"number":14,"options":["features","results","rules","tests"]},{"number":15,"options":["bored","anxious","sick","hungry"]},{"number":16,"options":["sign","secret","belief","principle"]},{"number":17,"options":["request","necessity","wish","decision"]},{"number":18,"options":["surprising","disappointing","restricting","consuming"]},{"number":19,"options":["if","unless","because","until"]},{"number":20,"options":["dominating","obsessing","puzzling","triumphing"]}],"sourcePages":[1,2]}'::jsonb,'published' from exam_sections s join exam_papers p on p.id=s.paper_id where p.year=2019 and s.type='cloze' on conflict(section_id) do update set content=excluded.content,status='published';
insert into private.cloze_keys(task_id,keys) select t.id,'[{"number":1,"answer":"C","explanation":"conflict：参考答案为C（Otherwise），但根据上下文，前句说定期称重是保持警觉的好方法，后句说做得太频繁可能有害，两者是转折关系，应选However（A）。Otherwise表示“否则”，逻辑不符。因此答案明显错误。"},{"number":2,"answer":"D","explanation":"conflict：参考答案为D（reduces），但此处意为“伤害大于帮助”，与hurt形成对比，应选helps（B）。reduces“减少”不能与hurt构成“伤害大于减少”的合理搭配。因此答案明显错误。"},{"number":3,"answer":"A","explanation":"conflict：参考答案为A（initially），但上下文说每天称重使焦点从整体健康转移到仅仅关注秤，强调唯一性，应选solely（C）。initially“最初”与“从……转移到……”的持续状态不符。因此答案明显错误。"},{"number":4,"answer":"A","explanation":"conflict：参考答案为A（recording），但此处指只想着降低秤上的数字，与后文“改变训练计划”导致肌肉增长目标冲突，应选lowering（C）。recording“记录”不能体现“只关注数字下降”的意图。因此答案明显错误。"},{"number":5,"answer":"C","explanation":"conflict：参考答案为C（review），但此处指与实现目标所需的训练方式相冲突，应选reach（A），“reach my goals”是固定搭配。review“回顾”目标不合逻辑。因此答案明显错误。"},{"number":6,"answer":"A","explanation":"conflict：参考答案为A（definition），但此处指每日称重不能提供努力和进步的准确描述，应选depiction（C），“accurate depiction”意为准确描绘。definition“定义”不搭配。因此答案明显错误。"},{"number":7,"answer":"D","explanation":"conflict：参考答案为D（along with），但此处指改变训练计划后需要三周到一个月才能注意到体重显著变化，表示原因，应选due to（B）。along with“连同”不表因果。因此答案明显错误。"},{"number":8,"answer":"C","explanation":"conflict：参考答案为C（precise），但此处指最明显的变化将在技能、力量和围度上观察到，应选immediate（A）或明显，precise“精确”不修饰changes。因此答案明显错误。"},{"number":9,"answer":"B","explanation":"conflict：参考答案为B（judgments），但此处指“由于这些原因”，应选reasons（D），“for these reasons”是固定搭配。judgments“判断”不搭配。因此答案明显错误。"},{"number":10,"answer":"D","explanation":"conflict：参考答案为D（indeed），但此处指停止每天称重，转而改为每月两次，表示替代，应选instead（B）。indeed“确实”不表替代。因此答案明显错误。"},{"number":11,"answer":"A","explanation":"conflict：第11题参考答案为A，但A对应report（报告），而上下文说“Since weight loss is not my goal, it is less important for me to {{11}} my weight each week”，意为减肥不是目标，所以每周追踪体重没那么重要。track（追踪）最合适，report（报告）不如track贴切。答案A（report）明显错误，故返回conflict。"},{"number":12,"answer":"C","explanation":"conflict：第12题参考答案为C，但C对应hold onto（保持），而上下文说“Weighing every other week allows me to observe and {{12}} any significant weight changes”，意为每两周称一次能观察并解释显著体重变化。account for（解释）最合适，hold onto（保持）不合逻辑。答案C明显错误，故返回conflict。"},{"number":13,"answer":"B","explanation":"conflict：第13题参考答案为B，但B对应share（分享），而上下文说“That tells me whether I need to {{13}} my training program”，意为这告诉我是否需要调整训练计划。adjust（调整）最合适，share（分享）不合逻辑。答案B明显错误，故返回conflict。"},{"number":14,"answer":"D","explanation":"conflict：第14题参考答案为D，但D对应tests（测试），而上下文说“I use my bimonthly weigh-in {{14}} to get information about my nutrition as well”，意为利用每两周称重的结果获取营养信息。results（结果）最合适，tests（测试）不搭配。答案D明显错误，故返回conflict。"},{"number":15,"answer":"B","explanation":"conflict：第15题参考答案为B，但B对应anxious（焦虑），而上下文说“If my training intensity remains the same, but I''m constantly {{15}} and dropping weight”，意为训练强度不变但持续饥饿且体重下降。hungry（饥饿）最合适，anxious（焦虑）不合逻辑。答案B明显错误，故返回conflict。"},{"number":16,"answer":"C","explanation":"conflict：第16题参考答案为C，但C对应belief（信念），而上下文说“this is a {{16}} that I need to increase my daily caloric intake”，意为这是需要增加每日热量摄入的信号。sign（信号）最合适，belief（信念）不合逻辑。答案C明显错误，故返回conflict。"},{"number":17,"answer":"B","explanation":"conflict：第17题参考答案为B，但B对应necessity（必要性），而上下文说“The {{17}} to stop weighing myself every day has done wonders”，意为停止每天称重的决定带来了奇效。decision（决定）最合适，necessity（必要性）不搭配。答案B明显错误，故返回conflict。"},{"number":18,"answer":"D","explanation":"conflict：第18题参考答案为D，但D对应consuming（消耗），而上下文说“I no longer carry the burden of a {{18}} morning weigh-in”，意为不再背负令人失望的晨称负担。disappointing（令人失望的）最合适，consuming（消耗）不合逻辑。答案D明显错误，故返回conflict。"},{"number":19,"answer":"A","explanation":"conflict：第19题参考答案为A，但A对应if（如果），而上下文说“I''ve also experienced greater success in achieving my specific fitness goals, {{19}} I''m training according to those goals”，意为因为按目标训练所以更成功。because（因为）最合适，if（如果）不合逻辑。答案A明显错误，故返回conflict。"},{"number":20,"answer":"D","explanation":"conflict：第20题参考答案为D，但D对应triumphing（胜利），而上下文说“Rather than {{20}} over the scale, turn your focus to how you look”，意为不要纠结于体重秤。obsessing（痴迷）最合适，triumphing（胜利）不合逻辑。答案D明显错误，故返回conflict。"}]'::jsonb from cloze_tasks t join exam_sections s on s.id=t.section_id join exam_papers p on p.id=s.paper_id where p.year=2019 on conflict(task_id) do update set keys=excluded.keys;
insert into exam_sections(paper_id,type,item_count,position,status) select id,'cloze',1,1,'published' from exam_papers where year=2020 on conflict(paper_id,type) do update set item_count=1,status='published';
insert into cloze_tasks(section_id,content,status) select s.id,'{"year":2020,"directions":"Read the following text. Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET. (10 points)","paragraphs":["Being a good parent is what every parent would like to be. But defining what it means to be a good parent is undoubtedly very {{1}} , particularly since children respond differently to the same style of parenting. A calm, rule-following child might respond better to a different sort of parenting than, {{2}} , a younger one.","{{3}} , there’s another sort of parent that’s easier to {{4}} : a patient parent. Children of every age benefit from patient parenting. Still, {{5}} every parent would like to be patient, this is no easy {{6}} . Sometimes, parents get exhausted and are unable to maintain a {{7}} style with their kids. I understand this.","You’re only human, and sometimes your kids can {{8}} you just a little too far. And then the {{9}} happens: You lose your patience and either scream at your kids or say something that was too {{10}} and does nobody any good. You wish that you could {{11}} the clock and start over. We’ve all been there.","{{12}} , even though it’s common, it’s vital to keep in mind that in a single moment of fatigue, you can say something to your child that you may {{13}} for a long time. This may not only do damage to your relationship with your child but also {{14}} your child’s self-esteem.","If you consistently lose your {{15}} with your kids, then you are modeling a lack of emotional control for your kids. We are all becoming increasingly aware of the {{16}} of modeling patience for the younger generation. This is a skill that will help them all throughout life. In fact, the ability to maintain emotional control when {{17}} by stress is one of the most significant of all life’s skills.","Certainly, it’s {{18}} to maintain patience at all times with your kids. A more practical goal is to try to be as calm as you can when faced with {{19}} situations involving your children. I can promise you this: As a result of working toward this goal, you and your children will benefit and {{20}} from stressful moments feeling better physically and emotionally."],"questions":[{"number":1,"options":["tedious","pleasant","instructive","tricky"]},{"number":2,"options":["in addition","for example","at once","by accident"]},{"number":3,"options":["Fortunately","Occasionally","Accordingly","Eventually"]},{"number":4,"options":["amuse","assist","describe","train"]},{"number":5,"options":["while","because","unless","once"]},{"number":6,"options":["answer","task","choice","access"]},{"number":7,"options":["tolerant","formal","rigid","critical"]},{"number":8,"options":["move","drag","push","send"]},{"number":9,"options":["mysterious","illogical","suspicious","inevitable"]},{"number":10,"options":["boring","naive","harsh","vague"]},{"number":11,"options":["turn back","take apart","set aside","cover up"]},{"number":12,"options":["Overall","Instead","However","Otherwise"]},{"number":13,"options":["like","miss","believe","regret"]},{"number":14,"options":["raise","affect","justify","reflect"]},{"number":15,"options":["time","bond","race","cool"]},{"number":16,"options":["nature","secret","importance","context"]},{"number":17,"options":["cheated","defeated","confused","confronted"]},{"number":18,"options":["terrible","hard","strange","wrong"]},{"number":19,"options":["trying","changing","exciting","surprising"]},{"number":20,"options":["hide","emerge","withdraw","escape"]}],"sourcePages":[1,2]}'::jsonb,'published' from exam_sections s join exam_papers p on p.id=s.paper_id where p.year=2020 and s.type='cloze' on conflict(section_id) do update set content=excluded.content,status='published';
insert into private.cloze_keys(task_id,keys) select t.id,'[{"number":1,"answer":"D","explanation":"空格前说“定义好父母意味着什么无疑非常……”，后文解释因为孩子对同样教养方式反应不同，说明定义起来很棘手。tricky意为“棘手的、微妙的”，符合语境。tedious“乏味的”、pleasant“愉快的”、instructive“有教益的”都不能体现定义困难这一逻辑。"},{"number":2,"answer":"B","explanation":"前句说“一个冷静、守规则的孩子可能对另一种教养方式反应更好”，空格后“a younger one”是举出另一个孩子作例子，与前面形成对比举例。for example“例如”正好引出具体例子。in addition表递进、at once“立刻”、by accident“偶然”均不符合举例逻辑。"},{"number":3,"answer":"A","explanation":"上文说定义好父母很难，本句转而说“还有另一种更容易描述的父母：有耐心的父母”，从困难转向较易说明，语气是积极的转折。Fortunately“幸运的是”符合这种庆幸语气。Occasionally“偶尔”、Accordingly“因此”、Eventually“最终”都不能体现这种语义转折。"},{"number":4,"answer":"C","explanation":"空格所在句说“还有另一种更容易……的父母：有耐心的父母”，冒号后给出定义，说明这种父母容易被描述。describe“描述”与defining呼应。amuse“逗乐”、assist“帮助”、train“训练”都不能与“另一种父母”构成定义关系。"},{"number":5,"answer":"A","explanation":"本句意为“尽管每位父母都想有耐心，但这绝非易事”，前后是让步关系。while可表“虽然、尽管”，引导让步状语从句。because表原因、unless表条件、once表时间，均不能表达“虽然……但……”的逻辑。"},{"number":6,"answer":"B","explanation":"空格前说“每位父母都想有耐心”，空格后说“这绝非易事”，no easy task是固定搭配，意为“不是容易的事”。answer“答案”、choice“选择”、access“途径”都不能与no easy构成“不易做到的任务”这一搭配。"},{"number":7,"answer":"A","explanation":"上文强调耐心，本句说父母疲惫时无法对孩子保持……的风格。tolerant意为“宽容的、忍耐的”，与patient语义一致。formal“正式的”、rigid“僵硬的”、critical“挑剔的”都不符合“有耐心”的语境。"},{"number":8,"answer":"C","explanation":"本句说“孩子有时会把你……得有点太过分”，push sb. too far是固定表达，意为“把某人逼得太甚”。move“移动”、drag“拖拽”、send“发送”都不能与too far构成“逼人过度”的习语。"},{"number":9,"answer":"D","explanation":"空格后冒号解释“你失去耐心，冲孩子喊叫或说难听的话”，这是疲惫时几乎必然发生的事。inevitable“不可避免的”符合语境。mysterious“神秘的”、illogical“不合逻辑的”、suspicious“可疑的”都不能概括这种常见后果。"},{"number":10,"answer":"C","explanation":"空格处修饰“说的话”，与scream并列，且后文说“对谁都没好处”，说明话很伤人。harsh意为“严厉的、刺耳的”，符合语境。boring“无聊的”、naive“天真的”、vague“含糊的”都不能体现伤害性。"},{"number":11,"answer":"A","explanation":"此处表达希望时光倒流、重新开始。turn back the clock是固定搭配，意为“让时光倒流”，符合语境。take apart意为“拆开”，set aside意为“搁置”，cover up意为“掩盖”，均不能与clock搭配表达此意。"},{"number":12,"answer":"C","explanation":"前文说失去耐心很常见，后文强调其危害，此处需转折关系。However表示“然而”，引出重要提醒。Overall表总结，Instead表替代，Otherwise表否则，均不符合逻辑。"},{"number":13,"answer":"D","explanation":"句意：一时疲惫说出的话，你可能会后悔很久。regret for a long time搭配合理，表示长期懊悔。like, miss, believe均不能与for a long time搭配表达“后悔”之意。"},{"number":14,"answer":"B","explanation":"此处与do damage to并列，说明对孩子自尊的负面影响。affect意为“影响”，可指不良影响，符合语境。raise意为“提高”，justify意为“证明合理”，reflect意为“反映”，均不恰当。"},{"number":15,"answer":"D","explanation":"lose one’s cool是固定习语，意为“失去冷静、发脾气”，与后文modeling a lack of emotional control呼应。lose time, bond, race均无此习语含义。"},{"number":16,"answer":"C","explanation":"句意：我们越来越意识到为年轻一代树立耐心榜样的重要性。importance意为“重要性”，符合aware of的搭配和上下文。nature, secret, context均不能表达“重要性”这一核心含义。"},{"number":17,"answer":"D","explanation":"此处指面对压力时保持情绪控制的能力。confronted by stress意为“面临压力”，符合语境。cheated, defeated, confused均不能与by stress搭配表达“面对压力”之意。"},{"number":18,"answer":"B","explanation":"句意：当然，始终对孩子保持耐心是很难的。hard意为“困难的”，与后文a more practical goal形成对比。terrible, strange, wrong均不符合此处客观陈述的语气。"},{"number":19,"answer":"A","explanation":"此处指涉及孩子的令人头疼的情境。trying意为“令人恼火的、难对付的”，符合语境。changing, exciting, surprising均不能准确描述需要保持耐心的困难情境。"},{"number":20,"answer":"B","explanation":"句意：努力实现这一目标后，你和孩子都将受益，并在压力时刻过后身心感觉更好。emerge from意为“从……中出来/摆脱”，符合语境。hide, withdraw, escape均不能与from stressful moments搭配表达“度过压力时刻”之意。"}]'::jsonb from cloze_tasks t join exam_sections s on s.id=t.section_id join exam_papers p on p.id=s.paper_id where p.year=2020 on conflict(task_id) do update set keys=excluded.keys;
insert into exam_sections(paper_id,type,item_count,position,status) select id,'cloze',1,1,'published' from exam_papers where year=2021 on conflict(paper_id,type) do update set item_count=1,status='published';
insert into cloze_tasks(section_id,content,status) select s.id,'{"year":2021,"directions":"Read the following text. Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET. (10 points)","paragraphs":["It’s not difficult to set targets for staff. It is much harder, {{1}} , to understand their negative consequences. Most work-related behaviors have multiple components. {{2}} one and the others become distorted.","Travel on a London bus and you’ll {{3}} see how this works with drivers. Watch people get on and show their tickets. Are they carefully inspected? Never. Do people get on without paying? Of course! Are there inspectors to {{4}} that people have paid? Possibly, but very few. And people who run for the bus? They are {{5}} . How about jumping lights? Buses do so almost as frequently as cyclists.","Why? Because the target is {{6}} . People complained that buses were late and infrequent. {{7}} , the number of buses and bus lanes were increased, and drivers were {{8}} or punished according to the time they took. And drivers hit these targets. But they {{9}} hit cyclists. If the target was changed to {{10}} , you would have more inspectors and more sensitive pricing. If the criterion changed to safety, you would get more {{11}} drivers who obeyed traffic laws. But both these criteria would be at the expense of time.","There is another {{12}} : people became immensely inventive in hitting targets. Have you {{13}} that you can leave on a flight an hour late but still arrive on time? Tailwinds? Of course not! Airlines have simply changed the time a {{14}} is meant to take. A one-hour flight is now billed as a two-hour flight.","The {{15}} of the story is simple. Most jobs are multidimensional, with multiple criteria. Choose one criterion and you may well {{16}} others. Everything can be done faster and made cheaper, but there is a {{17}} . Setting targets can and does have unforeseen negative consequences.","This is not an argument against target-setting. But it is an argument for exploring consequences first. All good targets should have multiple criteria {{18}} critical factors such as time, money, quality and customer feedback. The trick is not only to {{19}} just one or even two dimensions of the objective, but also to understand how to help people better {{20}} the objective."],"questions":[{"number":1,"options":["therefore","however","again","moreover"]},{"number":2,"options":["Emphasize","Identify","Assess","Explain"]},{"number":3,"options":["nearly","curiously","eagerly","quickly"]},{"number":4,"options":["claim","prove","check","recall"]},{"number":5,"options":["ignored","threatened","mocked","blamed"]},{"number":6,"options":["punctuality","hospitality","competition","innovation"]},{"number":7,"options":["Yet","So","Besides","Still"]},{"number":8,"options":["hired","trained","rewarded","grouped"]},{"number":9,"options":["only","rather","once","also"]},{"number":10,"options":["comfort","revenue","efficiency","security"]},{"number":11,"options":["friendly","quiet","cautious","diligent"]},{"number":12,"options":["purpose","problem","prejudice","policy"]},{"number":13,"options":["reported","revealed","admitted","noticed"]},{"number":14,"options":["break","trip","departure","transfer"]},{"number":15,"options":["moral","background","style","form"]},{"number":16,"options":["interpret","criticize","sacrifice","tolerate"]},{"number":17,"options":["task","secret","product","cost"]},{"number":18,"options":["leading to","calling for","relating to","accounting for"]},{"number":19,"options":["specify","predict","restore","create"]},{"number":20,"options":["modify","review","present","achieve"]}],"sourcePages":[1,2]}'::jsonb,'published' from exam_sections s join exam_papers p on p.id=s.paper_id where p.year=2021 and s.type='cloze' on conflict(section_id) do update set content=excluded.content,status='published';
insert into private.cloze_keys(task_id,keys) select t.id,'[{"number":1,"answer":"B","explanation":"空格前说“设定目标不难”，空格后说“理解其负面后果难得多”，前后为转折关系，故选however。therefore表因果，again表重复，moreover表递进，均不符合逻辑。"},{"number":2,"answer":"A","explanation":"前文说多数工作行为有多个组成部分，本句说“强调一个，其他就会扭曲”，Emphasize意为“强调”，符合语境。Identify“识别”、Assess“评估”、Explain“解释”均不能体现偏重某一方面的含义。"},{"number":3,"answer":"D","explanation":"本句意为“乘坐伦敦巴士，你很快就能看到这一点如何运作”，quickly表示“很快地”，符合语境。nearly“几乎”、curiously“好奇地”、eagerly“急切地”均不恰当。"},{"number":4,"answer":"C","explanation":"本句问“是否有检查员来核查人们已经付款”，check意为“核查”，符合语境。claim“声称”、prove“证明”、recall“回忆”均不能与that从句搭配表示核查。"},{"number":5,"answer":"B","explanation":"前文说人们追公交车，本句说“他们被无视”，ignored意为“被忽视”，符合语境。threatened“被威胁”、mocked“被嘲笑”、blamed“被责备”均不符合上下文。"},{"number":6,"answer":"A","explanation":"后文提到人们抱怨公交车晚点且班次少，于是增加车辆和车道，并根据司机用时奖惩，说明目标是“准时”，punctuality意为“准时”，符合语境。hospitality“好客”、competition“竞争”、innovation“创新”均不相关。"},{"number":7,"answer":"B","explanation":"前文说人们抱怨，后文说因此增加了车辆和车道，So表示因果，符合逻辑。Yet表转折，Besides表递进，Still表转折，均不恰当。"},{"number":8,"answer":"C","explanation":"本句说根据司机用时对他们进行奖励或惩罚，rewarded意为“奖励”，与punished形成对比，符合语境。hired“雇佣”、trained“培训”、grouped“分组”均不能与punished并列。"},{"number":9,"answer":"D","explanation":"前文说司机达到了这些目标，本句说“但他们也撞到了骑自行车的人”，also意为“也”，表示并列，符合语境。only“仅仅”、rather“相当”、once“一旦”均不恰当。"},{"number":10,"answer":"B","explanation":"后文说如果标准改为安全，会有更多谨慎的司机，本句说如果目标改为“收入”，就会有更多检查员和更敏感的价格，revenue意为“收入”，符合语境。comfort“舒适”、efficiency“效率”、security“安全”均与后文安全标准重复或无关。"},{"number":11,"answer":"C","explanation":"空格所在句说若标准改为安全，就会有更多遵守交规的司机。cautious“谨慎的”与obeyed traffic laws语义一致，修饰司机最贴切。friendly“友好的”、quiet“安静的”与交规无关；diligent“勤奋的”强调努力，不直接对应安全驾驶。"},{"number":12,"answer":"B","explanation":"前文讲设定单一目标带来负面后果，此处引出另一个问题：人们为达标而“创造性”地做表面文章。problem“问题”承接上文负面逻辑。purpose“目的”、prejudice“偏见”、policy“政策”均不能概括这种负面现象。"},{"number":13,"answer":"D","explanation":"句意为“你是否注意到航班晚起飞一小时却仍准点到达？”noticed“注意到”与宾语从句所述日常现象搭配自然。reported“报告”、revealed“揭示”多用于正式发现；admitted“承认”含认错意味，不合语境。"},{"number":14,"answer":"B","explanation":"航空公司改变了航班“预计飞行时间”，a trip is meant to take指一段行程所需时间，trip“行程”符合。break“休息”、departure“出发”、transfer“转乘”均不能与take搭配表示飞行时长。"},{"number":15,"answer":"A","explanation":"本段总结全文寓意，the moral of the story是固定搭配，意为“故事的寓意/教训”。background“背景”、style“风格”、form“形式”均不能与of the story构成此习语。"},{"number":16,"answer":"C","explanation":"选择一项标准就可能“牺牲”其他标准，与后文at the expense of呼应。sacrifice“牺牲”准确表达取舍。interpret“解释”、criticize“批评”、tolerate“容忍”均不能表达因偏重一项而损害其他的逻辑。"},{"number":17,"answer":"D","explanation":"一切都能更快更便宜，但存在“代价”，there is a cost为固定表达，且与上文at the expense of及负面后果呼应。task“任务”、secret“秘密”、product“产品”均不合逻辑。"},{"number":18,"answer":"C","explanation":"好的目标应有多重标准，涉及时间、金钱、质量等关键因素。relating to“涉及、关于”准确连接标准与因素。leading to“导致”、calling for“要求”、accounting for“解释”均不能表达标准涵盖这些因素之意。"},{"number":19,"answer":"A","explanation":"诀窍不仅在于“明确”目标的一个或两个维度，specify“明确指定”与dimensions of the objective搭配合理。predict“预测”、restore“恢复”、create“创造”均不能与“明确目标维度”对应。"},{"number":20,"answer":"D","explanation":"不仅要明确目标维度，还要帮助人们更好地“实现”目标。achieve the objective是常见搭配。modify“修改”、review“审查”、present“呈现”均不能表达达成目标之意。"}]'::jsonb from cloze_tasks t join exam_sections s on s.id=t.section_id join exam_papers p on p.id=s.paper_id where p.year=2021 on conflict(task_id) do update set keys=excluded.keys;
insert into exam_sections(paper_id,type,item_count,position,status) select id,'cloze',1,1,'published' from exam_papers where year=2022 on conflict(paper_id,type) do update set item_count=1,status='published';
insert into cloze_tasks(section_id,content,status) select s.id,'{"year":2022,"directions":"Read the following text. Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET. (10 points)","paragraphs":["Harlan Coben believes that if you’re a writer, you’ll find the time; and that if you can’t find the time, then writing isn’t a priority and you’re not a writer. For him, writing is a {{1}} job — a job like any other. He has {{2}} it with plumbing, pointing out that a plumber doesn’t wake up and say that he can’t work with pipes today.","{{3}} , like most writers these days, you’re holding down a job to pay the bills, it’s not {{4}} to find the time to write. But it’s not impossible. It requires determination and single-mindedness. {{5}} that most bestselling authors began writing when they were doing other things to earn a living. And today, even writers who are fairly {{6}} often have to do other work to {{7}} their writing income.","As Harlan Coben has suggested, it’s a {{8}} of priorities. To make writing a priority, you’ll have to {{9}} Some of your day-to-day activities and some things you really enjoy. Depending on your {{10}} and your lifestyle, that might mean spending less time watching television or listening to music, though some people can write {{11}} they listen to music. You might have to {{12}} the amount of exercise or sport you do. You’ll have to make social media an {{13}} activity rather than a daily, time-consuming {{14}} . There’ll probably have to be less socialising with your friends and less time with your family. It’s a {{15}} learning curve and it won’t always make you popular.","There’s just one thing you should try to keep at least some time for, {{16}} your writing — and that’s reading. Any writer needs to read as much and as widely as they can; it’s the one {{17}} supporter — Something you can’t do without.","Time is finite. The older you get, the {{18}} it seems to go. We need to use it as carefully and as {{19}} as we can. That means prioritising out activities so that we spend most time on the things we really want to do. If you are a writer, that means — {{20}} — writing."],"questions":[{"number":1,"options":["difficult","normal","steady","pleasant"]},{"number":2,"options":["combined","compared","confused","confronted"]},{"number":3,"options":["If","Though","Once","Unless"]},{"number":4,"options":["enough","strange","wrong","easy"]},{"number":5,"options":["Accept","Explain","Remember","Suppose"]},{"number":6,"options":["well-known","well-advised","well-informed","well-chosen"]},{"number":7,"options":["donate","generate","supplement","calculate"]},{"number":8,"options":["cause","purpose","question","condition"]},{"number":9,"options":["highlight","sacrifice","continue","explore"]},{"number":10,"options":["relations","interests","memories","skills"]},{"number":11,"options":["until","because","while","before"]},{"number":12,"options":["put up with","make up for","hang on to","cut down on"]},{"number":13,"options":["intelligent","occasional","intensive","emotional"]},{"number":14,"options":["habit","test","decision","plan"]},{"number":15,"options":["tough","gentle","rapid","funny"]},{"number":16,"options":["in place of","in charge of","in response to","in addition to"]},{"number":17,"options":["indispensable","innovative","invisible","instant"]},{"number":18,"options":["duller","harder","quieter","quicker"]},{"number":19,"options":["peacefully","generously","productively","gratefully"]},{"number":20,"options":["at most","in turn","on average","above all"]}],"sourcePages":[1,2]}'::jsonb,'published' from exam_sections s join exam_papers p on p.id=s.paper_id where p.year=2022 and s.type='cloze' on conflict(section_id) do update set content=excluded.content,status='published';
insert into private.cloze_keys(task_id,keys) select t.id,'[{"number":1,"answer":"B","explanation":"空前说“写作是像其他工作一样的工作”，normal job 表示“普通、平常的工作”，与 a job like any other 呼应。difficult 强调难度，steady 强调稳定，pleasant 强调愉快，均不能体现“与别的工作无异”这一语义。"},{"number":2,"answer":"B","explanation":"compare A with B 意为“把A比作B”，后文“pointing out that a plumber...”正是把写作与水管工工作作比较。combined 搭配 with 表“与……结合”，confused 表“困惑”，confronted 表“面对”，均不合“作类比”的语境。"},{"number":3,"answer":"A","explanation":"此处提出“你像多数作家一样要打工付账单”这一前提，后文说“找时间写作不容易”，前后是条件关系，用 If 引导条件状语从句。Though 表让步，Once 表“一旦”，Unless 表否定条件，均不能自然衔接这一假设情形。"},{"number":4,"answer":"D","explanation":"前文说“要打工付账单”，因此“找时间写作”是“不容易的”，it’s not easy to find the time 符合逻辑。enough 不能作表语表“足够”；strange“奇怪”、wrong“错误”与后文“但并非不可能”不构成转折呼应。"},{"number":5,"answer":"C","explanation":"后文“多数畅销作家开始写作时都在做别的工作谋生”是作者提醒读者注意的事实，Remember that... 意为“要记住……”。Accept 表接受，Explain 表解释，Suppose 表假设，均不能引出这一客观提醒。"},{"number":6,"answer":"A","explanation":"even writers who are fairly well-known 指“甚至相当知名的作家”，与后文“仍要做其他工作补充写作收入”形成让步。well-advised“明智的”、well-informed“消息灵通的”、well-chosen“精选的”均不能修饰作家表“知名”。"},{"number":7,"answer":"C","explanation":"作家做其他工作是为了“补充”写作收入，supplement 意为“增补、补充”，与 their writing income 搭配自然。donate 表捐赠，generate 表产生，calculate 表计算，均不能表达“弥补写作收入不足”之意。"},{"number":8,"answer":"C","explanation":"a question of priorities 是固定表达，意为“优先次序问题”，与后文“把写作列为优先”直接对应。cause 表原因，purpose 表目的，condition 表条件，均不能与 priorities 构成“……的问题”这一搭配。"},{"number":9,"answer":"B","explanation":"后文列举“少看电视、少运动、少社交”等，说明要把写作放优先就得“牺牲”一些日常活动，sacrifice 符合语境。highlight 表突出，continue 表继续，explore 表探索，均与“减少享受之事”的逻辑相反。"},{"number":10,"answer":"B","explanation":"depending on your interests and your lifestyle 意为“取决于你的兴趣和生活方式”，后文“少看电视或听音乐”正属于个人兴趣范畴。relations 表关系，memories 表记忆，skills 表技能，均不能与“少看电视、听音乐”这类选择自然对应。"},{"number":11,"answer":"C","explanation":"此处说有些人可以“一边听音乐一边写作”，while 表示“当……时、与……同时”，符合上下文对比：有人需少听音乐，有人却能边听边写。until 表“直到”，because 表因果，before 表先后，均不能表达同时进行的伴随关系。"},{"number":12,"answer":"D","explanation":"前文列举要减少看电视、听音乐的时间，此处接着说可能得“减少”锻炼或运动量。cut down on 意为“削减、减少”，与上下文“牺牲日常活动”一致。put up with 是忍受，make up for 是弥补，hang on to 是保留，均与“减少”相反。"},{"number":13,"answer":"B","explanation":"此处与 rather than a daily, time-consuming {{14}} 对照，强调社交媒体应成为“偶尔的”活动，而非每天耗时的习惯。occasional 意为“偶尔的”，符合“减少使用”的逻辑。intelligent、intensive、emotional 均不能与 activity 搭配表达频率上的对比。"},{"number":14,"answer":"A","explanation":"此处指社交媒体不应成为每天耗时的一种“习惯”。habit 意为“习惯”，与 daily、time-consuming 搭配自然，且与前面的 occasional activity 形成对照。test、decision、plan 都无法表达“每天反复做、耗费时间”的含义。"},{"number":15,"answer":"A","explanation":"前文说要多牺牲娱乐社交、可能不受欢迎，可见学习曲线是“艰难的”。tough 意为“艰难的、棘手的”，符合语境。gentle 是温和的，rapid 是快速的，funny 是有趣的，都不能概括这种需要付出代价的调整过程。"},{"number":16,"answer":"D","explanation":"前文说写作要优先、要牺牲许多事，此处转折：有一件事应留出时间，即“除写作之外”的阅读。in addition to 意为“除……之外（还）”，符合“写作之外还要保留阅读”的逻辑。in place of 是代替，in charge of 是负责，in response to 是回应，均不通。"},{"number":17,"answer":"A","explanation":"此处说阅读是“不可或缺的”支持者，是离不开的东西。indispensable 意为“必不可少的”，与后文 something you can’t do without 直接呼应。innovative 是创新的，invisible 是看不见的，instant 是立即的，都不能表达“离不开”之意。"},{"number":18,"answer":"D","explanation":"此处说人越老，时间似乎过得越“快”。quicker 意为“更快”，与 the older you get 形成对照，符合“时间飞逝”的常见表达。duller、harder、quieter 都不能与 go 搭配表示时间流逝的速度。"},{"number":19,"answer":"C","explanation":"此处说我们要尽可能仔细且“高效地”利用时间。productively 意为“有成效地”，与 use it as carefully and as... 并列，强调时间利用的效率。peacefully、generously、gratefully 均不能修饰利用时间的方式。"},{"number":20,"answer":"D","explanation":"全文结论：若你是作家，那就意味着“最重要的是”写作。above all 意为“首先、最重要的是”，呼应前文“把写作列为优先”。at most 是至多，in turn 是依次，on average 是平均，都不能表达强调首要性的逻辑。"}]'::jsonb from cloze_tasks t join exam_sections s on s.id=t.section_id join exam_papers p on p.id=s.paper_id where p.year=2022 on conflict(task_id) do update set keys=excluded.keys;
insert into exam_sections(paper_id,type,item_count,position,status) select id,'cloze',1,1,'published' from exam_papers where year=2023 on conflict(paper_id,type) do update set item_count=1,status='published';
insert into cloze_tasks(section_id,content,status) select s.id,'{"year":2023,"directions":"Read the following text. Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET. (10 points)","paragraphs":["Here’s a common scenario that any number of entrepreneurs face today: you’re the CEO of a small business, and though you’re making a nice {{1}} , you need to find a way to take it to the next level. What you need to do is {{2}} growth by establishing a growth team. A growth team is made up of members from different departments within your company, and it harnesses the power of collaboration to focus {{3}} on finding ways to grow.","Let’s look at a real-world {{4}} . Prior to forming a growth team, the software company BitTorrent had 50 employees working in the {{5}} departments of engineering, marketing and product development. This brought them good results until 2012, when their growth plateaued. The {{6}} was that too many customers were using the basic, free version of their product. And {{7}} improvements to the premium, paid version, few people were making the upgrade.","Things changed, {{8}} , when an innovative project-marketing manager came aboard, {{9}} a growth team and sparked the kind of {{10}} perspective they needed. By looking at engineering issues from a marketing point of view, it became clear that the {{11}} of upgrades wasn’t due to a quality issue. Most customers were simply unaware of the premium version and what it offered.","Armed with this {{12}} , the marketing and engineering teams joined forces to raise awareness by prominently {{13}} the premium version to users of the free version. {{14}} , upgrades skyrocketed, and revenue increased by 92 percent.","But in order for your growth team to succeed, it needs to have a strong leader. It needs someone who can {{15}} the interdisciplinary team and keep them on course for improvement. This leader will {{16}} the target area, set clear goals and establish a time frame for the {{17}} of these goals.","The growth leader is also {{18}} for keeping the team focused on moving forward and steering them clear of distractions. {{19}} attractive, new ideas can be distracting, the team leader must recognize when these ideas don’t {{20}} the current goal and need to be put on the back burner."],"questions":[{"number":1,"options":["purchase","profit","connection","bet"]},{"number":2,"options":["define","predict","prioritize","appreciate"]},{"number":3,"options":["exclusively","temporarily","potentially","initially"]},{"number":4,"options":["experiment","proposal","debate","example"]},{"number":5,"options":["identical","marginal","provisional","traditional"]},{"number":6,"options":["rumor","secret","myth","problem"]},{"number":7,"options":["despite","unlike","through","besides"]},{"number":8,"options":["moreover","however","therefore","again"]},{"number":9,"options":["inspected","created","expanded","reformed"]},{"number":10,"options":["cultural","objective","fresh","personal"]},{"number":11,"options":["end","burden","lack","decrease"]},{"number":12,"options":["policy","suggestion","purpose","insight"]},{"number":13,"options":["contributing","allocating","promoting","transferring"]},{"number":14,"options":["As a result","At any rate","By the way","In a sense"]},{"number":15,"options":["unite","finance","follow","choose"]},{"number":16,"options":["share","identify","divide","broaden"]},{"number":17,"options":["announcement","assessment","adjustment","accomplishment"]},{"number":18,"options":["famous","responsible","available","respectable"]},{"number":19,"options":["Before","Once","While","Unless"]},{"number":20,"options":["serve","limit","summarize","alter"]}],"sourcePages":[1,2]}'::jsonb,'published' from exam_sections s join exam_papers p on p.id=s.paper_id where p.year=2023 and s.type='cloze' on conflict(section_id) do update set content=excluded.content,status='published';
insert into private.cloze_keys(task_id,keys) select t.id,'[{"number":1,"answer":"B","explanation":"此处说小企业CEO虽在赚“不错的利润”，却需把生意提升到新层次。profit指经济收益，与making搭配自然，符合企业家语境。purchase（购买）、connection（联系）、bet（赌注）均不能表示经营所得，语义不通。"},{"number":2,"answer":"C","explanation":"后文说通过建立增长团队来推动增长，说明需要把增长“优先考虑”。prioritize意为优先处理，与growth搭配合理。define（定义）、predict（预测）、appreciate（欣赏）都不能体现把增长置于首位的行动逻辑。"},{"number":3,"answer":"A","explanation":"增长团队汇集跨部门协作之力，集中“专门”寻找增长途径。exclusively表示专一地、排他地，强调聚焦。temporarily（暂时）、potentially（潜在）、initially（最初）均不能突出协作力量集中用于增长这一目的。"},{"number":4,"answer":"D","explanation":"下文举BitTorrent公司实例，故此处说看一个现实“例子”。example与real-world搭配，引出具体案例。experiment（实验）、proposal（提议）、debate（辩论）都不能自然衔接后文的公司事例叙述。"},{"number":5,"answer":"D","explanation":"BitTorrent原有50名员工分布在工程、市场、产品开发这些“传统”部门。traditional修饰departments，指常规职能部门。identical（完全相同）、marginal（边缘的）、provisional（临时的）都不符合公司部门设置的常理。"},{"number":6,"answer":"D","explanation":"前文说增长停滞，后文解释太多客户只用免费版，这是症结所在，故填problem。rumor（谣言）、secret（秘密）、myth（迷思）都不能指增长停滞的实际原因，problem与was that结构搭配自然。"},{"number":7,"answer":"A","explanation":"尽管对付费高级版做了改进，升级的人仍很少，前后为让步关系，用despite。unlike（不像）、through（通过）、besides（此外）都不能表达“虽然有改进却仍少人升级”的转折让步逻辑。"},{"number":8,"answer":"B","explanation":"前段讲停滞困境，此处说情况改变了，语意转折，用however。moreover（而且）、therefore（因此）、again（再次）均不能体现从困境到转机的对比关系。"},{"number":9,"answer":"B","explanation":"一位有创新精神的项目营销经理加入后“创建”了增长团队。created与a growth team搭配，表示组建团队。inspected（检查）、expanded（扩大）、reformed（改革）都不能准确表达从无到有建立团队。"},{"number":10,"answer":"C","explanation":"该经理带来营销视角，激发团队所需的“新颖”视角。fresh perspective指新鲜、不同角度的看法，与后文从营销角度看工程问题呼应。cultural（文化的）、objective（客观的）、personal（个人的）都不贴合跨部门新视角之意。"},{"number":11,"answer":"C","explanation":"空格所在句说升级问题并非质量问题，后文说顾客根本不知道付费版，可见问题是升级“缺乏”，lack of upgrades 意为升级不足，与 Most customers were simply unaware 呼应。end 指结束，burden 指负担，decrease 指减少，均不能说明“没人升级”这一数量不足的含义。"},{"number":12,"answer":"D","explanation":"this {{12}} 回指上段发现“顾客不了解付费版”这一认识，insight 意为“洞察、深刻认识”，正合语境。policy 政策、suggestion 建议、purpose 目的都不能指代前文调查得出的认识，搭配 armed with this insight 也自然。"},{"number":13,"answer":"C","explanation":"团队合力提高认知度，方式是对免费版用户突出地“推广”付费版，promoting 意为宣传推广，与 raise awareness 逻辑一致。contributing 贡献、allocating 分配、transferring 转移都不能与 the premium version to users 搭配表达推广之意。"},{"number":14,"answer":"A","explanation":"前文说推广付费版，后文说升级猛增、收入增长92%，两者是因果承接关系，As a result 意为“结果”，最贴切。At any rate 无论如何、By the way 顺便说、In a sense 在某种意义上，都不能体现推广带来的直接结果。"},{"number":15,"answer":"A","explanation":"本句说成长团队需要能“团结”跨部门团队并使其朝改进方向前进的领导者，unite 意为联合、凝聚，符合领导者角色。finance 资助、follow 跟随、choose 选择都不能与 the interdisciplinary team 搭配表达统领凝聚之意。"},{"number":16,"answer":"B","explanation":"领导者要先“确定”目标领域，再设定清晰目标，identify 意为识别、确定，与后文 set clear goals 构成先后动作。share 分享、divide 划分、broaden 拓宽都不能准确表达锁定目标领域这一管理动作。"},{"number":17,"answer":"D","explanation":"领导者为目标的“实现”设定时间表，accomplishment 意为完成、实现，the accomplishment of these goals 搭配自然。announcement 宣布、assessment 评估、adjustment 调整都不能与 time frame for the ___ of goals 构成“完成目标”的常见表达。"},{"number":18,"answer":"B","explanation":"be responsible for 意为“负责”，句意为成长领导者还负责让团队专注前进、避开干扰，与上段 needs to have a strong leader 的职责描述一致。famous 著名的、available 可获得的、respectable 可敬的都不能与 for keeping 搭配表达职责。"},{"number":19,"answer":"C","explanation":"此处表示“虽然新想法很吸引人，但可能分散注意力”，While 引导让步状语从句，意为“虽然”，与主句 the team leader must recognize 形成转折。Before 在……之前、Once 一旦、Unless 除非，逻辑均不通。"},{"number":20,"answer":"A","explanation":"领导者要识别这些新想法何时不“服务于”当前目标，需要搁置，serve 意为有助于、符合，serve the current goal 搭配合理。limit 限制、summarize 总结、alter 改变都不能表达“与当前目标无关、无助于目标”之意。"}]'::jsonb from cloze_tasks t join exam_sections s on s.id=t.section_id join exam_papers p on p.id=s.paper_id where p.year=2023 on conflict(task_id) do update set keys=excluded.keys;
insert into exam_sections(paper_id,type,item_count,position,status) select id,'cloze',1,1,'published' from exam_papers where year=2024 on conflict(paper_id,type) do update set item_count=1,status='published';
insert into cloze_tasks(section_id,content,status) select s.id,'{"year":2024,"directions":"Read the following text. Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET. (10 points)","paragraphs":["Your social life is defined as “the activities you do with other people, for pleasure, when you are not working.” It’s important to have a social life, but what’s right for one person won’t be right for another. Some of us feel energised by spending lots of time with others, {{1}} some of us may feel drained, even if it’s doing something we enjoy.","This is why finding a {{2}} in your social life is key. Spending too much time on your own, not {{3}} others, can make you feel lonely and {{4}} . Loneliness is known to impact on your mental health and {{5}} a low mood. Anyone can feel lonely at any time. This might be especially true if, {{6}} , you are working from home and you are {{7}} on the usual social conversations that happen in an office. Other life changes can {{8}} periods of loneliness too, such as retirement, changing jobs or becoming a parent.","It’s important to recognise these feelings of loneliness. There are ways to {{9}} a social life, but it can feel overwhelming {{10}} . It’s a great idea to start by thinking about hobbies you enjoy. You can then find groups and activities related to those where you will be able to meet {{11}} people. There are groups aimed at new parents, at those who want to {{12}} a new sport for the first time, or networking events for those in the same profession to meet up and {{13}} ideas.","On the other hand, it’s {{14}} possible to have too much of a social life. If you feel like you’re always doing something and there is never any {{15}} in your calendar for downtime, you could suffer social burnout or social {{16}} . We all have our own social limit and it’s important to recognise when you’re feeling like it’s all too much. Low mood, low energy, irritability and trouble sleeping could all be {{17}} of poor social health. Make sure you {{18}} some time in your diary when you’re {{19}} for socialising and use this time to relax, {{20}} and recover."],"questions":[{"number":1,"options":["because","unless","whereas","until"]},{"number":2,"options":["contrast","balance","link","gap"]},{"number":3,"options":["seeing","pleasing","judging","teaching"]},{"number":4,"options":["misguided","surprised","spoiled","disconnected"]},{"number":5,"options":["contribute to","rely on","interfere with","go against"]},{"number":6,"options":["in fact","of course","for example","on average"]},{"number":7,"options":["cutting back","missing out","breaking in","looking down"]},{"number":8,"options":["shorten","trigger","follow","interrupt"]},{"number":9,"options":["assess","interpret","provide","regain"]},{"number":10,"options":["at first","in turn","on time","by chance"]},{"number":11,"options":["far-sighted","strong-willed","kind-hearted","like-minded"]},{"number":12,"options":["try","promote","watch","describe"]},{"number":13,"options":["test","share","accept","revise"]},{"number":14,"options":["already","thus","also","only"]},{"number":15,"options":["list","order","space","boundary"]},{"number":16,"options":["fatigue","criticism","injustice","dilemma"]},{"number":17,"options":["sources","standards","signs","scores"]},{"number":18,"options":["take over","wipe off","add up","mark out"]},{"number":19,"options":["ungrateful","unavailable","responsible","regretful"]},{"number":20,"options":["react","repeat","return","rest"]}],"sourcePages":[1,2]}'::jsonb,'published' from exam_sections s join exam_papers p on p.id=s.paper_id where p.year=2024 and s.type='cloze' on conflict(section_id) do update set content=excluded.content,status='published';
insert into private.cloze_keys(task_id,keys) select t.id,'[{"number":1,"answer":"C","explanation":"此处对比两类人：有人与人相处获得能量，另一些人则感到疲惫。whereas表对比转折，连接前后相反情况，符合语境。because表因果、unless表条件、until表时间，均无法体现这种对照关系。"},{"number":2,"answer":"B","explanation":"下文说独处太久会孤独，后文又说社交过多也会倦怠，说明社交生活需要“平衡”。balance意为平衡，与key搭配自然。contrast对比、link联系、gap差距均不能概括适度社交这一核心。"},{"number":3,"answer":"A","explanation":"not seeing others指不与他人见面往来，与spending too much time on your own并列，说明孤立状态导致孤独。seeing符合“见人、交往”的语义。pleasing取悦、judging评判、teaching教导均与孤独成因无关。"},{"number":4,"answer":"D","explanation":"空格与lonely并列，描述缺乏社交的负面感受。disconnected意为与人脱节、疏离，契合不与他人来往的语境。misguided被误导、surprised惊讶、spoiled被宠坏都不属于孤独带来的感受。"},{"number":5,"answer":"A","explanation":"孤独影响心理健康并“导致”情绪低落，contribute to表示促成、助长某种结果，搭配a low mood合理。rely on依赖、interfere with干扰、go against违背均不能表达孤独与低落情绪之间的因果方向。"},{"number":6,"answer":"C","explanation":"前句说任何人都可能孤独，此处举居家办公为例说明尤其如此，for example引出例证，逻辑顺畅。in fact表强调、of course表当然、on average表平均，都不能自然引出这一具体情形。"},{"number":7,"answer":"B","explanation":"居家办公者会“错过”办公室里常见的社交交谈，missing out on意为错失、得不到，符合语境。cutting back削减、breaking in闯入、looking down轻视均与错过日常交流的语义不符。"},{"number":8,"answer":"B","explanation":"退休、换工作、为人父母等生活变化也会“引发”孤独期，trigger意为触发、引起，搭配periods of loneliness恰当。shorten缩短、follow跟随、interrupt打断都不能表达这些变化导致孤独的含义。"},{"number":9,"answer":"D","explanation":"本段讲应对孤独的办法，regain a social life意为重新获得、重建社交生活，与后文从爱好入手找群体相呼应。assess评估、interpret解释、provide提供均不能与a social life构成“恢复社交”的合理搭配。"},{"number":10,"answer":"A","explanation":"重建社交生活虽可行，但“起初”会让人不知所措，at first表示开始时，与后文建议先从小处着手形成呼应。in turn依次、on time按时、by chance偶然都不符合这一转折语气。"},{"number":11,"answer":"D","explanation":"空格前说找到与爱好相关的团体和活动，目的是“遇到____的人”。like-minded意为“志趣相投的”，与因共同爱好聚集的语境吻合。far-sighted“有远见的”、strong-willed“意志坚定的”、kind-hearted“善良的”均无法体现共同兴趣这一核心逻辑。"},{"number":12,"answer":"A","explanation":"此处列举面向新父母的团体、面向想首次____新运动的人。try a new sport意为“尝试一项新运动”，与for the first time呼应。promote“推广”对象不当，watch“观看”与参与团体活动不符，describe“描述”更无关联。"},{"number":13,"answer":"B","explanation":"networking events for those in the same profession to meet up and ____ ideas，同行聚会的目的应是交流想法。share ideas是固定搭配，意为“交流/分享想法”。test“检验”、accept“接受”、revise“修改”均不能与meet up并列表达同行互动的目的。"},{"number":14,"answer":"C","explanation":"上一段讲如何重建社交生活，本段开头On the other hand转折，指出社交过多同样可能有害。also possible表示“也有可能”，与too much of a social life呼应。already、thus、only均不能准确表达“另一方面也存在这种可能”的逻辑。"},{"number":15,"answer":"C","explanation":"if you feel like you''re always doing something and there is never any ____ in your calendar for downtime，指日程里没有空闲时间。space意为“空档、余地”，与for downtime搭配自然。list“清单”、order“顺序”、boundary“界限”均不能表达日历中缺乏空闲之意。"},{"number":16,"answer":"A","explanation":"suffer social burnout or social ____，与burnout并列，应指社交过度导致的身心疲惫。fatigue意为“疲劳”，social fatigue即“社交疲劳”，符合语境。criticism“批评”、injustice“不公”、dilemma“困境”均不能与burnout构成同义并列。"},{"number":17,"answer":"C","explanation":"Low mood, low energy, irritability and trouble sleeping could all be ____ of poor social health，这些表现是社交健康不佳的“迹象”。signs of意为“……的迹象”，搭配准确。sources“来源”、standards“标准”、scores“分数”均不能概括这些症状与社交健康的关系。"},{"number":18,"answer":"D","explanation":"Make sure you ____ some time in your diary，指在日记中“标出/留出”一段时间。mark out意为“标出、划出”，与in your diary搭配合理。take over“接管”、wipe off“擦去”、add up“加起来”均不符合“预留时间”之意。"},{"number":19,"answer":"B","explanation":"when you''re ____ for socialising and use this time to relax，指在“不便于/没空”社交的时候留出时间休息。unavailable for意为“无法进行……的”，与后文relax and recover逻辑一致。ungrateful“不感激的”、responsible“负责的”、regretful“后悔的”均不能与for socialising搭配表达没空社交。"},{"number":20,"answer":"D","explanation":"use this time to relax, ____ and recover，三个动词并列，应是与relax、recover同义的休息类动作。rest意为“休息”，最贴合。react“反应”、repeat“重复”、return“返回”均不能与relax和recover构成语义一致的并列。"}]'::jsonb from cloze_tasks t join exam_sections s on s.id=t.section_id join exam_papers p on p.id=s.paper_id where p.year=2024 on conflict(task_id) do update set keys=excluded.keys;
insert into exam_sections(paper_id,type,item_count,position,status) select id,'cloze',1,1,'published' from exam_papers where year=2025 on conflict(paper_id,type) do update set item_count=1,status='published';
insert into cloze_tasks(section_id,content,status) select s.id,'{"year":2025,"directions":"Read the following text. Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET. (10 points)","paragraphs":["There are many understandable reasons why you might find it difficult to ask for help when you need it. Psychologists have been interested in this {{1}} for decades, not least because people’s widespread {{2}} to ask for help has led to some high-profile failures.","Asking for help takes {{3}} . It involves communicating a need on your part — there’s something you can’t do. {{4}} , you’re broadcasting your own weakness, which can be {{5}} . You might have {{6}} about losing control of whatever it is you are asking for help with. {{7}} someone starts to help, perhaps they will take over, or get a credit for your early efforts. Yet another {{8}} that you might be worried about is being a nuisance or {{9}} the person you go to for help.","If you struggle with low self-esteem, you might find it especially difficult to {{10}} for help because you have the added worry of the other person {{11}} your request. You might see such refusals as implying something {{12}} about the status of your relationship with them. To {{13}} these difficulties, try to remind yourself that everyone needs help sometimes. Nobody knows everything and can do everything all by themselves. And while you might {{14}} coming across as incompetent, there’s actually research that shows that advice-seekers are {{15}} as more competent, not less.","Perhaps most encouraging of all is a paper from 2022 by researchers at Stanford University, in California, that involved a mix of contrived help-seeking interactions and asking people to {{16}} times they’d sought help in the past. The findings showed that help-seekers generally underestimate how {{17}} other people will be to help and how good it will make the help-giver feel (for most people, having the chance to help someone is highly {{18}} ).","So bear all this in mind the next time you need to ask for help. {{19}} , take care over who you ask and when you ask them. And if someone can’t help right now, avoid taking it personally. They might just be too {{20}} , or they might not feel confident about their ability to help."],"questions":[{"number":1,"options":["illusion","discussion","tradition","question"]},{"number":2,"options":["reluctance","ambition","tendency","enthusiasm"]},{"number":3,"options":["attention","talent","courage","patience"]},{"number":4,"options":["At any time","In other words","By all means","On the contrary"]},{"number":5,"options":["unrealistic","deceptive","tiresome","uncomfortable"]},{"number":6,"options":["doubts","concerns","suggestions","secrets"]},{"number":7,"options":["Once","Unless","Although","Before"]},{"number":8,"options":["theory","choice","factor","context"]},{"number":9,"options":["overpraising","outperforming","reassessing","inconveniencing"]},{"number":10,"options":["reach out","settle down","turn over","look back"]},{"number":11,"options":["declining","considering","criticizing","evaluating"]},{"number":12,"options":["unnecessary","negative","strange","impractical"]},{"number":13,"options":["explain","identify","predict","overcome"]},{"number":14,"options":["deny","forget","miss","fear"]},{"number":15,"options":["disguised","perceived","followed","introduced"]},{"number":16,"options":["recall","classify","analyse","compare"]},{"number":17,"options":["brave","disapproving","willing","hesitant"]},{"number":18,"options":["relaxing","surprising","rewarding","demanding"]},{"number":19,"options":["Thus","Also","Finally","Instead"]},{"number":20,"options":["polite","proud","busy","lazy"]}],"sourcePages":[1,2]}'::jsonb,'published' from exam_sections s join exam_papers p on p.id=s.paper_id where p.year=2025 and s.type='cloze' on conflict(section_id) do update set content=excluded.content,status='published';
insert into private.cloze_keys(task_id,keys) select t.id,'[{"number":1,"answer":"D","explanation":"空格前说“人们难以求助”，心理学家感兴趣的是这一“问题/现象”。question 在此可指“问题、议题”，与 this 搭配自然。illusion“错觉”与后文“广泛不愿求助导致失败”不符；discussion“讨论”和 tradition“传统”都无法概括这一心理现象。"},{"number":2,"answer":"A","explanation":"后文说这种态度“导致了一些高调的失败”，说明人们普遍“不愿”求助。reluctance to ask for help 意为“不愿求助”，语义和搭配都成立。ambition“雄心”与求助语境矛盾；tendency 虽可接 to，但“倾向求助”与失败逻辑相反；enthusiasm“热情”更与不愿求助相反。"},{"number":3,"answer":"C","explanation":"本段讲求助要暴露自己的弱点、担心失控和被抢功，因此求助需要“勇气”。take courage 是固定搭配，意为“需要勇气”。attention“注意力”、talent“才能”、patience“耐心”都不能概括后文所强调的心理风险与胆量。"},{"number":4,"answer":"B","explanation":"前句说“你在传达自己有个需求——有件事你做不了”，后句说“你在暴露自己的弱点”，后者是对前者的换一种说法。In other words“换句话说”正好承接。At any time“随时”、By all means“当然可以”、On the contrary“相反”都不符合解释关系。"},{"number":5,"answer":"D","explanation":"暴露自己的弱点会让人感到“不舒服”，与段首“求助需要勇气”呼应。uncomfortable 指心理上的不自在。unrealistic“不现实”不修饰这种感受；deceptive“欺骗性的”与暴露弱点无关；tiresome“令人厌烦的”侧重他人感受，不如 uncomfortable 贴切。"},{"number":6,"answer":"B","explanation":"后文“担心一旦有人帮忙，也许他们会接管，或者抢走你早期努力的功劳”正是求助前的“担忧”。have concerns about 意为“对……有担忧”，搭配自然。doubts 多指怀疑某事真假，不如 concerns 贴合“担心失控”；suggestions“建议”、secrets“秘密”均不合逻辑。"},{"number":7,"answer":"A","explanation":"此处表示“一旦有人开始帮忙，也许他们就会接管”，Once 引导条件/时间状语，意为“一旦”，与 perhaps 搭配自然。Unless“除非”逻辑相反；Although“虽然”不表条件；Before“在……之前”与“开始帮忙后接管”的语义不符。"},{"number":8,"answer":"C","explanation":"前文列举了“暴露弱点”“担心失控”等担忧，此处说“又一个你可能担心的……是成为讨厌的人”，factor 意为“因素”，可指担忧的一个方面。theory“理论”、choice“选择”、context“背景”都不能与“又一个担忧”对应。"},{"number":9,"answer":"D","explanation":"与“being a nuisance”并列，应指给求助对象“添麻烦”。inconveniencing 意为“给……带来不便”，与 the person you go to for help 搭配合理。overpraising“过度赞扬”、outperforming“超过”、reassessing“重新评估”都不属于求助时担心造成的负面后果。"},{"number":10,"answer":"A","explanation":"本句说“如果你自尊心低，你可能会发现尤其难以……求助”，reach out for help 意为“主动寻求帮助”，与后文“担心对方拒绝你的请求”衔接。settle down“安定下来”、turn over“翻转”、look back“回顾”都不能与 for help 构成“求助”之意。"},{"number":11,"answer":"A","explanation":"此处说低自尊者额外担心对方会拒绝请求，declining your request 意为“拒绝你的请求”，与后文 refusals 呼应。considering（考虑）、criticizing（批评）、evaluating（评估）都不表示拒绝，无法与下句的 refusals 形成照应。"},{"number":12,"answer":"B","explanation":"句意为把拒绝看作暗示你们关系状况的负面信号，negative 与低自尊者容易消极解读的心理相符。unnecessary（不必要的）、strange（奇怪的）、impractical（不切实际的）都不能准确修饰对关系状况的暗示，且与后文鼓励性建议的逻辑相反。"},{"number":13,"answer":"D","explanation":"to overcome these difficulties 意为“克服这些困难”，指克服前文所述求助时的种种心理障碍。explain（解释）、identify（识别）、predict（预测）都不能与 difficulties 搭配表达“战胜困难”之意，且后文提醒自己人人需要帮助正是为了克服困难。"},{"number":14,"answer":"D","explanation":"fear coming across as incompetent 意为“担心显得无能”，与上文 broadcasting your own weakness 的担忧一脉相承。deny（否认）、forget（忘记）、miss（错过）都不能表达对给人留下无能印象的忧虑，且与 while 转折后“研究显示求助者被认为更能干”的对比不成立。"},{"number":15,"answer":"B","explanation":"be perceived as more competent 意为“被认为更能干”，perceived 与 as 搭配表示“被视为”。disguised（伪装）、followed（跟随）、introduced（介绍）都不能与 as more competent 构成“被认为”的含义，也无法与上文 fear 形成转折对比。"},{"number":16,"answer":"A","explanation":"recall times they''d sought help 意为“回忆过去求助的经历”，与实验让受试者回想往事的做法相符。classify（分类）、analyse（分析）、compare（比较）都不符合“回忆过去求助时刻”这一研究设计，且与 recall 相比缺少对个人经历的提取含义。"},{"number":17,"answer":"C","explanation":"how willing other people will be to help 意为“别人有多愿意帮忙”，willing 与 be to help 搭配自然。brave（勇敢的）、disapproving（不赞成的）、hesitant（犹豫的）都与研究发现“求助者低估他人帮助意愿”的结论不符，hesitant 更与低估之意相反。"},{"number":18,"answer":"C","explanation":"having the chance to help someone is highly rewarding 意为“有机会帮助别人很有回报感”，rewarding 与括号内解释帮助者感受的语境一致。relaxing（放松的）、surprising（令人惊讶的）、demanding（要求高的）都不能说明帮助他人带来的积极心理体验。"},{"number":19,"answer":"B","explanation":"Also 表示递进，在前文“记住这些”之外补充“还要注意向谁求助、何时求助”。Thus（因此）表因果、Finally（最后）表顺序收尾、Instead（相反）表转折，都与此处并列补充建议的逻辑不符。"},{"number":20,"answer":"C","explanation":"They might just be too busy 意为“他们可能只是太忙了”，与后文“或对帮助能力没信心”并列解释对方无法帮忙的原因。polite（礼貌的）、proud（骄傲的）、lazy（懒惰的）都不能合理解释“现在帮不了你”，且 lazy 带有贬义，不符合善意归因的语气。"}]'::jsonb from cloze_tasks t join exam_sections s on s.id=t.section_id join exam_papers p on p.id=s.paper_id where p.year=2025 on conflict(task_id) do update set keys=excluded.keys;
insert into exam_sections(paper_id,type,item_count,position,status) select id,'cloze',1,1,'published' from exam_papers where year=2026 on conflict(paper_id,type) do update set item_count=1,status='published';
insert into cloze_tasks(section_id,content,status) select s.id,'{"year":2026,"directions":"Read the following text. Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET. (10 points)","paragraphs":["Most of us strive for self-respect — to see ourselves in a positive light, to be {{1}} of who we are. Any comments or experiences that undermine those feelings of self-worth can be uncomfortable and it’s only {{2}} to want to avoid them. But the thing is, {{3}} your self-worth really is being undermined is, to a large degree, subjective. Much of it comes down to your {{4}} of what someone said or did.","When you take things personally, you’re interpreting these situations as saying something significant and negative about you as a person. Say your boss picks holes in your sales report, and you come away feeling like this means she thinks you’re a {{5}} member of staff. Or, two of your friends cancel your {{6}} get-together at the pub and you interpret this as meaning they’re bored of you. Psychologists have a {{7}} for this way of thinking: personalisation.","But the {{8}} is that your boss might view you very highly. It’s just you made some {{9}} in the report and she wanted to point these out so that you do better next time. {{10}} , in the case of your friends cancelling, perhaps they both felt unwell that weekend or they just {{11}} their minds.","In both {{12}} — and others that we all experience — there’s another {{13}} at work that psychologists call mind reading. This is when you assume to know what other people are thinking about you, when you can’t really know without {{14}} them directly.","One simple way to avoid {{15}} personalisation and mind reading is to challenge your negative assumptions of what’s {{16}} . When you find yourself taking a situation personally, try to think of other interpretations that are less focused on you — especially in the sense of saying anything deep or {{17}} about you.","When you do this, it might help to try to put yourself in other people’s shoes. The fact your boss took the time to give you {{18}} at all means they care enough to want to help you {{19}} . When it comes to your friends — maybe it’s because your friendship is so {{20}} that they felt able to cancel at late notice."],"questions":[{"number":1,"options":["afraid","critical","proud","tolerant"]},{"number":2,"options":["risky","natural","admirable","foolish"]},{"number":3,"options":["whether","where","why","how"]},{"number":4,"options":["citation","imitation","perception","introduction"]},{"number":5,"options":["poor","loyal","creative","shy"]},{"number":6,"options":["sponsored","crowded","disputed","planned"]},{"number":7,"options":["method","term","design","goal"]},{"number":8,"options":["evidence","theory","condition","reality"]},{"number":9,"options":["complaints","choices","mistakes","suggestions"]},{"number":10,"options":["Similarly","Relatively","Accordingly","Contrarily"]},{"number":11,"options":["opened","changed","trained","cleared"]},{"number":12,"options":["quotations","experiments","questions","examples"]},{"number":13,"options":["process","objective","outcome","background"]},{"number":14,"options":["blaming","warning","teaching","asking"]},{"number":15,"options":["arguing about","accounting for","engaging in","interfering with"]},{"number":16,"options":["happened","continued","returned","disappeared"]},{"number":17,"options":["casual","obvious","familiar","fundamental"]},{"number":18,"options":["reward","feedback","trust","proof"]},{"number":19,"options":["innovate","concentrate","improve","relax"]},{"number":20,"options":["strange","strong","vulnerable","valuable"]}],"sourcePages":[1,2]}'::jsonb,'published' from exam_sections s join exam_papers p on p.id=s.paper_id where p.year=2026 and s.type='cloze' on conflict(section_id) do update set content=excluded.content,status='published';
insert into private.cloze_keys(task_id,keys) select t.id,'[{"number":1,"answer":"C","explanation":"空格前说“以积极眼光看待自己”，proud of who we are“为自己是谁而自豪”与self-respect语义一致。afraid“害怕”、critical“挑剔”、tolerant“容忍”均不能表达自我肯定的正面含义，且与positive light逻辑不符。"},{"number":2,"answer":"B","explanation":"前文说损害自我价值感的评论令人不适，因此想回避它们是“自然的”反应。natural符合“人之常情”的语境。risky“有风险”、admirable“令人钦佩”、foolish“愚蠢”都带有评价色彩，与only...to want to avoid them的客观陈述不搭配。"},{"number":3,"answer":"A","explanation":"此处引出核心观点：你的自我价值是否真的被损害，很大程度上是主观的。whether引导主语从句，表示“是否”，与后文to a large degree, subjective呼应。where、why、how均无法表达“是否”这一不确定性含义。"},{"number":4,"answer":"C","explanation":"句意：这很大程度上取决于你对别人言行所作的“解读/认知”。perception of“对……的感知”与come down to搭配自然。citation“引用”、imitation“模仿”、introduction“介绍”均与对他人言行的理解无关。"},{"number":5,"answer":"A","explanation":"老板挑销售报告的毛病，你便觉得她认为你是“差劲的”员工。poor member of staff符合负面解读的语境。loyal“忠诚”、creative“有创意”、shy“害羞”都不能与picks holes in（挑刺）形成因果呼应。"},{"number":6,"answer":"D","explanation":"朋友取消的是“事先计划好的”pub聚会。planned get-together“计划好的聚会”搭配自然。sponsored“赞助的”、crowded“拥挤的”、disputed“有争议的”均不能修饰朋友间的常规聚会。"},{"number":7,"answer":"B","explanation":"心理学家对这种思维方式有专门的“术语”：personalisation。term“术语”与have a...for this way of thinking搭配恰当。method“方法”、design“设计”、goal“目标”都不能指称一个心理学术语。"},{"number":8,"answer":"D","explanation":"前文是“你”的主观解读，此处用But转折引出“现实”情况：老板可能对你评价很高。reality“现实”与主观臆断形成对比。evidence“证据”、theory“理论”、condition“条件”均不能承担这一转折。"},{"number":9,"answer":"C","explanation":"老板指出报告中的“错误”，目的是让你下次做得更好。mistakes in the report与point these out（指出）搭配自然。complaints“抱怨”、choices“选择”、suggestions“建议”都不能与point out形成“指出问题”的语义。"},{"number":10,"answer":"A","explanation":"前句解释老板的情况，此处转而解释朋友取消聚会的情况，两者是并列类比关系，故用Similarly“同样地”。Relatively“相对地”、Accordingly“因此”、Contrarily“相反地”都不符合两个例子并列的逻辑。"},{"number":11,"answer":"B","explanation":"此处说朋友取消聚会，也许他们周末身体不适，或者只是“改变了主意”。change one''s mind 是固定搭配，意为“改变想法”，与上文取消聚会的语境吻合。open/train/clear 均不能与 minds 构成“改变主意”之意，故排除。"},{"number":12,"answer":"D","explanation":"In both examples 意为“在这两个例子中”，指代上文老板挑错和朋友取消聚会两个具体事例。quotations（引文）、experiments（实验）、questions（问题）都不符合此处举例归纳的语境，故 examples 最贴切。"},{"number":13,"answer":"A","explanation":"此处说还有另一种心理“过程”在起作用，即心理学家所称的“读心术”。process 指心理运作过程，与 at work（在起作用）搭配自然。objective（目标）、outcome（结果）、background（背景）都不能表达“心理机制运作”之意。"},{"number":14,"answer":"D","explanation":"句意为：你假定知道别人怎么看你，而不直接“问”他们就无法真正知道。asking 与 them directly 搭配，指直接询问对方，符合语境。blaming（责备）、warning（警告）、teaching（教导）都与“获知他人想法”的逻辑不符。"},{"number":15,"answer":"C","explanation":"avoid engaging in personalisation and mind reading 意为“避免陷入/参与人格化和读心术”。engage in 表示“从事、参与某种行为”，与这两种思维模式搭配恰当。argue about（争论）、account for（解释）、interfere with（干扰）均不合语义。"},{"number":16,"answer":"A","explanation":"challenge your negative assumptions of what''s happened 意为“质疑你对所发生之事的消极假设”。happened 与 assumptions of what''s... 构成“对已发生事情的假设”，符合上下文。continued/returned/disappeared 都无法表达“已发生的事”这一含义。"},{"number":17,"answer":"D","explanation":"especially in the sense of saying anything deep or fundamental about you 意为“尤其是就说明你身上任何深层或根本性的东西而言”。fundamental 与 deep 并列，强调“根本的”，符合语境。casual（随意的）、obvious（明显的）、familiar（熟悉的）都不能与 deep 形成递进强调。"},{"number":18,"answer":"B","explanation":"老板花时间给你 feedback（反馈），指对销售报告提出意见。feedback 与前文 picks holes in your sales report、point these out 呼应。reward（奖励）、trust（信任）、proof（证据）都不符合“指出报告问题”的语境。"},{"number":19,"answer":"C","explanation":"老板给反馈是希望帮助你 improve（改进、提高），即下次做得更好。improve 与前文 do better next time 呼应。innovate（创新）、concentrate（集中）、relax（放松）都不符合“改进工作表现”之意。"},{"number":20,"answer":"B","explanation":"句意为：朋友能临时取消，也许正因为你们的友谊如此 strong（牢固），才觉得可以晚通知。strong 修饰 friendship 表示“牢固的友谊”，与 able to cancel at late notice 的逻辑相符。strange/vulnerable/valuable 都不能表达“关系牢固所以随意”之意。"}]'::jsonb from cloze_tasks t join exam_sections s on s.id=t.section_id join exam_papers p on p.id=s.paper_id where p.year=2026 on conflict(task_id) do update set keys=excluded.keys;
